window.ETSDATA=window.ETSDATA||{};window.ETSDATA[29]={"lc":{"p1":[{"n":1,"opts":["The man is looking at a laptop computer.","The man is writing on a notepad.","The man is talking on the phone.","The man is opening some curtains."],"vi":["Người đàn ông đang nhìn máy tính xách tay.","Người đàn ông đang viết lên sổ tay.","Người đàn ông đang nói chuyện điện thoại.","Người đàn ông đang kéo rèm."],"ans":"B","xp":"Tranh: người đàn ông cúi xuống viết trên tập giấy → (B). Có laptop trên bàn nhưng ông không nhìn vào nó (A sai).","a":"XC-T09-01.mp3","img":"q1.jpg"},{"n":2,"opts":["They are wearing gloves.","They are lifting a desk.","A woman is setting up a sign.","A man is pushing a cart."],"vi":["Họ đang đeo găng tay.","Họ đang nâng một cái bàn.","Một người phụ nữ đang dựng biển báo.","Một người đàn ông đang đẩy xe đẩy."],"ans":"A","xp":"Tranh: hai người dọn vệ sinh, cả hai đều đeo găng tay → (A). Biển báo đã dựng sẵn (C sai), xe đẩy đứng yên (D sai).","a":"XC-T09-02.mp3","img":"q2.jpg"},{"n":3,"opts":["Some people are waiting for a bus.","A tree is being planted in a park.","A street light is being repaired.","A group of people are crossing a street."],"vi":["Một số người đang đợi xe buýt.","Một cái cây đang được trồng trong công viên.","Đèn đường đang được sửa.","Một nhóm người đang băng qua đường."],"ans":"D","xp":"Tranh: nhiều người đi trên vạch kẻ qua đường → (D).","a":"XC-T09-03.mp3","img":"q3.jpg"},{"n":4,"opts":["A hose is wound up in a sink.","A pot is being placed on a stove.","A container has been filled with tools.","A man is carrying a tool box."],"vi":["Ống nước được cuộn trong bồn rửa.","Một cái nồi đang được đặt lên bếp.","Một thùng chứa đầy dụng cụ.","Một người đàn ông đang xách hộp đồ nghề."],"ans":"C","xp":"Tranh: người thợ ngồi sửa đồ, cạnh đó có thùng đựng đầy dụng cụ → (C). Ông không xách hộp (D sai); cái nồi đã nằm sẵn, không ai đang đặt (B sai).","a":"XC-T09-04.mp3","img":"q4.jpg"},{"n":5,"opts":["Some boxes are stacked on top of each other.","The woman is leaning forward to reach for an item.","The man is making a purchase.","Some merchandise is being wrapped in paper."],"vi":["Một số hộp được xếp chồng lên nhau.","Người phụ nữ đang nghiêng người về phía trước để lấy một món đồ.","Người đàn ông đang mua hàng.","Một số hàng hóa đang được gói bằng giấy."],"ans":"B","xp":"Tranh: người phụ nữ nghiêng người với lấy món đồ → (B). Không có hộp chồng lên nhau, không ai đang trả tiền hay gói hàng.","a":"XC-T09-05.mp3","img":"q5.jpg"},{"n":6,"opts":["A ferry is approaching a bridge.","Some people are casting a net from a boat.","A ship is being unloaded at a pier.","Some buildings are located near water."],"vi":["Một chiếc phà đang tiến gần cây cầu.","Một số người đang quăng lưới từ thuyền.","Một con tàu đang được dỡ hàng ở bến.","Một số tòa nhà nằm gần mặt nước."],"ans":"D","xp":"Tranh: nhà cửa nằm dọc theo bờ sông → (D). Không có cầu, không có người (A)(B)(C) sai.","a":"XC-T09-06.mp3","img":"q6.jpg"}],"p2":[{"n":7,"q":"What time does the soccer championship game start on Thursday?","qvi":"Trận chung kết bóng đá vào thứ Năm bắt đầu lúc mấy giờ?","opts":["Which team do you support?","Kickoff is at 2 P.M.","Yes, you're correct."],"vi":["Bạn ủng hộ đội nào?","Trận đấu bắt đầu lúc 2 giờ chiều.","Vâng, bạn nói đúng."],"ans":"B","xp":"Câu hỏi What time → (B) 'Bắt đầu lúc 2 giờ chiều' (kickoff = giờ phát bóng). (C) Wh- không trả lời Yes.","a":"XC-T09-07.mp3"},{"n":8,"q":"Would you like to sit inside the café or outside on the patio?","qvi":"Bạn muốn ngồi trong quán hay ngoài hiên?","opts":["Inside would be better.","I ordered today's lunch special.","A table for four, please."],"vi":["Trong quán thì hơn.","Tôi đã gọi món trưa đặc biệt hôm nay.","Cho bàn bốn người."],"ans":"A","xp":"Câu hỏi lựa chọn → (A) 'Trong quán thì hơn'. (B)(C) liên tưởng quán cà phê.","a":"XC-T09-08.mp3"},{"n":9,"q":"Would you mind saving a seat for me?","qvi":"Bạn giữ giúp tôi một chỗ ngồi được không?","opts":["How many do you have?","Sure, that's no problem.","No, I missed the concert."],"vi":["Bạn có bao nhiêu cái?","Được chứ, không vấn đề gì.","Không, tôi đã lỡ buổi hòa nhạc."],"ans":"B","xp":"Lời nhờ → đồng ý (B). Lưu ý: với 'Would you mind...?', đáp 'Sure/No problem' là đồng ý giúp.","a":"XC-T09-09.mp3"},{"n":10,"q":"It feels a bit cold in the break room.","qvi":"Phòng nghỉ hơi lạnh.","opts":["Let's take a longer break.","Yes, I took medicine for it.","I can turn on the heater."],"vi":["Hãy nghỉ lâu hơn đi.","Vâng, tôi đã uống thuốc rồi.","Tôi có thể bật máy sưởi."],"ans":"C","xp":"Phàn nàn lạnh → đưa giải pháp: (C) 'Tôi bật máy sưởi'. (A) lặp từ break, (B) liên tưởng cold = cảm lạnh.","a":"XC-T09-10.mp3"},{"n":11,"q":"Where is the best place to buy a new vacuum cleaner?","qvi":"Mua máy hút bụi mới ở đâu tốt nhất?","opts":["Please start in the living room.","It has a very powerful motor.","Spencer Appliances has reasonable prices."],"vi":["Hãy bắt đầu từ phòng khách.","Nó có động cơ rất mạnh.","Cửa hàng Spencer Appliances giá hợp lý."],"ans":"C","xp":"Câu hỏi Where → (C) nêu tên cửa hàng. (A)(B) liên tưởng máy hút bụi.","a":"XC-T09-11.mp3"},{"n":12,"q":"When did you notice the problem with the printer?","qvi":"Bạn phát hiện máy in có vấn đề khi nào?","opts":["I can copy it for you.","The text looks blurry.","First thing this morning."],"vi":["Tôi có thể photo cho bạn.","Chữ trông bị mờ.","Ngay đầu giờ sáng nay."],"ans":"C","xp":"Câu hỏi When → (C). (B) trả lời 'vấn đề gì', không phải 'khi nào'.","a":"XC-T09-12.mp3"},{"n":13,"q":"What computer did you order?","qvi":"Bạn đã đặt mua máy tính nào?","opts":["Six hundred dollars.","A lightweight laptop.","To do my work assignments."],"vi":["Sáu trăm đô la.","Một chiếc laptop nhẹ.","Để làm bài tập công việc."],"ans":"B","xp":"Câu hỏi What computer (loại máy nào) → (B). (A) trả lời giá, (C) trả lời mục đích.","a":"XC-T09-13.mp3"},{"n":14,"q":"Can't the finance team issue the check early?","qvi":"Bộ phận tài chính không thể xuất séc sớm sao?","opts":["No, it must be done on the fifteenth.","Business expenses are reimbursed.","Yes, I'm a financial advisor."],"vi":["Không, phải làm vào ngày 15.","Chi phí công tác được hoàn lại.","Vâng, tôi là cố vấn tài chính."],"ans":"A","xp":"Câu hỏi phủ định → (A) 'Không, phải làm vào ngày 15'. (C) lặp âm finance/financial.","a":"XC-T09-14.mp3"},{"n":15,"q":"Why was the ice in the freezer melting?","qvi":"Sao đá trong ngăn đông lại tan?","opts":["Because the power went out.","An electronics store.","I'll take ice in my drink."],"vi":["Vì mất điện.","Một cửa hàng điện tử.","Tôi muốn bỏ đá vào đồ uống."],"ans":"A","xp":"Câu hỏi Why → (A) 'Vì mất điện'. (C) lặp từ ice.","a":"XC-T09-15.mp3"},{"n":16,"q":"Who's the lead researcher for this drug trial?","qvi":"Ai là trưởng nhóm nghiên cứu của đợt thử nghiệm thuốc này?","opts":["Dr. Cramer is overseeing it.","One of the main laboratories.","It will reduce flu symptoms."],"vi":["Bác sĩ Cramer đang phụ trách.","Một trong các phòng thí nghiệm chính.","Nó sẽ làm giảm triệu chứng cúm."],"ans":"A","xp":"Câu hỏi Who → (A) nêu tên người. (B)(C) liên tưởng nghiên cứu thuốc.","a":"XC-T09-16.mp3"},{"n":17,"q":"Are you going to renew the lease on your apartment?","qvi":"Bạn có định gia hạn hợp đồng thuê căn hộ không?","opts":["Yes, this is one of our newest products.","It depends on whether there's a rent increase.","Two bedrooms and a modern kitchen."],"vi":["Vâng, đây là một trong những sản phẩm mới nhất của chúng tôi.","Còn tùy tiền thuê có tăng không.","Hai phòng ngủ và bếp hiện đại."],"ans":"B","xp":"Trả lời 'còn tùy' → (B). (A) lặp âm renew/newest, (C) liên tưởng căn hộ.","a":"XC-T09-17.mp3"},{"n":18,"q":"Could you recommend a good sporting goods store?","qvi":"Bạn giới thiệu giúp một cửa hàng đồ thể thao tốt được không?","opts":["Basketball and baseball.","No, I usually watch games on TV.","I do all of my shopping online."],"vi":["Bóng rổ và bóng chày.","Không, tôi thường xem thi đấu trên TV.","Tôi mua sắm toàn bộ trên mạng."],"ans":"C","xp":"Trả lời gián tiếp 'tôi không biết cửa hàng nào' → (C) 'Tôi mua hết trên mạng'. (A)(B) liên tưởng thể thao.","a":"XC-T09-18.mp3"},{"n":19,"q":"Shouldn't we prepare name tags for the new team members?","qvi":"Chúng ta không nên chuẩn bị thẻ tên cho thành viên mới sao?","opts":["That's a good idea.","My name is Jessie Lee.","Welcome to your first day on the job."],"vi":["Ý hay đấy.","Tôi tên là Jessie Lee.","Chào mừng ngày đầu đi làm."],"ans":"A","xp":"Đề xuất → đồng ý (A). (B) lặp từ name, (C) liên tưởng nhân viên mới.","a":"XC-T09-19.mp3"},{"n":20,"q":"Why did we get charged extra for the rental car?","qvi":"Sao chúng ta bị tính thêm phí thuê xe?","opts":["I'll just take the subway.","At the nearest branch.","It wasn't returned on time."],"vi":["Tôi sẽ đi tàu điện ngầm.","Ở chi nhánh gần nhất.","Xe không được trả đúng hạn."],"ans":"C","xp":"Câu hỏi Why → (C) 'Vì xe trả trễ hạn'. (B) trả lời Where.","a":"XC-T09-20.mp3"},{"n":21,"q":"This bag will fit in the overhead compartment, won't it?","qvi":"Cái túi này để vừa ngăn hành lý phía trên, phải không?","opts":["Let's measure it again to check.","Thanks, it was too heavy for me.","I'm taking a flight to New Zealand."],"vi":["Hãy đo lại để kiểm tra.","Cảm ơn, nó nặng quá với tôi.","Tôi sẽ bay đến New Zealand."],"ans":"A","xp":"Trả lời gián tiếp 'chưa chắc' → (A) 'Đo lại để kiểm tra'. (B)(C) liên tưởng túi, chuyến bay.","a":"XC-T09-21.mp3"},{"n":22,"q":"What kind of visa will our client from Taiwan need?","qvi":"Khách hàng từ Đài Loan của chúng ta sẽ cần loại thị thực nào?","opts":["Ask Melanie in HR.","Yes, I've been there a few times.","I wish I would have thought of that."],"vi":["Hỏi Melanie ở phòng nhân sự.","Vâng, tôi đã đến đó vài lần.","Giá mà tôi nghĩ ra điều đó."],"ans":"A","xp":"Trả lời gián tiếp 'không biết, hỏi người khác' → (A). (B) Wh- không trả lời Yes.","a":"XC-T09-22.mp3"},{"n":23,"q":"Can I leave my briefcase in the conference room over lunch?","qvi":"Tôi để cặp tài liệu trong phòng họp trong giờ ăn trưa được không?","opts":["We won't be coming back here.","The product launch was a success.","Documents for the sales pitch."],"vi":["Chúng ta sẽ không quay lại đây.","Buổi ra mắt sản phẩm thành công.","Tài liệu cho buổi chào hàng."],"ans":"A","xp":"Xin phép → từ chối gián tiếp: (A) 'Chúng ta sẽ không quay lại phòng này' (nên đừng để đó). (C) liên tưởng cặp – tài liệu.","a":"XC-T09-23.mp3"},{"n":24,"q":"Why was this parcel returned to us?","qvi":"Sao bưu kiện này bị trả về?","opts":["Yes, we offer exchanges and refunds.","Yesterday morning, I think.","It had the wrong address."],"vi":["Vâng, chúng tôi có đổi trả và hoàn tiền.","Sáng hôm qua, tôi nghĩ vậy.","Nó bị ghi sai địa chỉ."],"ans":"C","xp":"Câu hỏi Why → (C) 'Ghi sai địa chỉ'. (A) Wh- không trả lời Yes, (B) trả lời When.","a":"XC-T09-24.mp3"},{"n":25,"q":"How can we attract more people to the apple picking event?","qvi":"Làm sao thu hút nhiều người hơn đến sự kiện hái táo?","opts":["It has an attractive design.","By lowering the entry fee.","Go to the registration booth."],"vi":["Nó có thiết kế hấp dẫn.","Bằng cách giảm phí vào cửa.","Hãy đến quầy đăng ký."],"ans":"B","xp":"Câu hỏi How (cách làm) → (B) 'By + V-ing'. (A) lặp âm attract/attractive.","a":"XC-T09-25.mp3"},{"n":26,"q":"There is a penalty for parking here.","qvi":"Đỗ xe ở đây sẽ bị phạt.","opts":["I don't mind giving you a ride.","You can borrow my pen.","Even for emergency vehicles?"],"vi":["Tôi không ngại chở bạn.","Bạn có thể mượn bút của tôi.","Kể cả xe cấp cứu sao?"],"ans":"C","xp":"Đáp lại thông báo bằng câu hỏi lại → (C) 'Kể cả xe cấp cứu sao?'. (B) lặp âm penalty/pen.","a":"XC-T09-26.mp3"},{"n":27,"q":"Who installed the wiring in your home?","qvi":"Ai lắp hệ thống dây điện trong nhà bạn?","opts":["Wireless Internet technology.","A five-day process.","I'll give you his business card."],"vi":["Công nghệ Internet không dây.","Một quy trình năm ngày.","Tôi sẽ đưa bạn danh thiếp của anh ấy."],"ans":"C","xp":"Câu hỏi Who → (C) 'Tôi đưa bạn danh thiếp của anh ấy' (người thợ). (A) lặp âm wiring/wireless.","a":"XC-T09-27.mp3"},{"n":28,"q":"Hasn't Erica completed the performance reviews?","qvi":"Erica chưa hoàn thành đánh giá năng lực nhân viên sao?","opts":["She's still on medical leave.","We really enjoyed the show.","She competed vigorously."],"vi":["Cô ấy vẫn đang nghỉ ốm.","Chúng tôi rất thích buổi diễn.","Cô ấy đã thi đấu hết mình."],"ans":"A","xp":"Trả lời gián tiếp 'chưa' → (A) 'Cô ấy vẫn đang nghỉ ốm'. (B) liên tưởng performance = buổi diễn, (C) lặp âm completed/competed.","a":"XC-T09-28.mp3"},{"n":29,"q":"How late does this restaurant serve breakfast?","qvi":"Nhà hàng này phục vụ bữa sáng đến mấy giờ?","opts":["Yes, I'll have the same thing.","The menu doesn't say.","Nine ninety-nine plus tax."],"vi":["Vâng, tôi gọi món giống vậy.","Thực đơn không ghi.","9,99 đô cộng thuế."],"ans":"B","xp":"Trả lời gián tiếp 'không biết' → (B) 'Thực đơn không ghi'. (C) trả lời giá.","a":"XC-T09-29.mp3"},{"n":30,"q":"Did you know the pharmacy is closing early today?","qvi":"Bạn có biết hôm nay hiệu thuốc đóng cửa sớm không?","opts":["These ingredients are from a nearby farm.","I have a doctor's appointment.","Then I'll have to pick up my prescription now."],"vi":["Những nguyên liệu này từ trang trại gần đây.","Tôi có hẹn bác sĩ.","Vậy tôi phải đi lấy thuốc theo đơn ngay bây giờ."],"ans":"C","xp":"Phản ứng với thông tin → (C) 'Vậy tôi phải lấy thuốc ngay'. (B) liên tưởng hiệu thuốc – bác sĩ.","a":"XC-T09-30.mp3"},{"n":31,"q":"You have a key to the side entrance, don't you?","qvi":"Bạn có chìa khóa cửa bên, phải không?","opts":["Mainly employees and delivery personnel.","It's on Amhurst Boulevard.","Yes, and I can open it for you."],"vi":["Chủ yếu là nhân viên và người giao hàng.","Nó ở đại lộ Amhurst.","Có, và tôi có thể mở cho bạn."],"ans":"C","xp":"Câu hỏi đuôi → (C) 'Có, tôi mở cho bạn'. (B) trả lời Where.","a":"XC-T09-31.mp3"}],"p3":[{"ns":[32,34],"script":[["M","Our store has just received a delivery of five crates of bottled water. Is this correct?","Cửa hàng mình vừa nhận năm thùng nước đóng chai. Vậy có đúng không?"],["W","Yes, there's a music festival at Mathis Park today. Since our supermarket is the only one in the neighborhood, a lot of people will be stopping by for snacks and drinks. It's going to be a busy day.","Đúng rồi, hôm nay có lễ hội âm nhạc ở công viên Mathis. Vì siêu thị mình là siêu thị duy nhất trong khu, nhiều người sẽ ghé mua đồ ăn vặt và đồ uống. Hôm nay sẽ bận lắm."],["M","Oh, I see. Do we need to call some extra staff members to come in?","À, tôi hiểu rồi. Mình có cần gọi thêm nhân viên đến không?"],["W","Ms. Newton has already done that. And I'll move the bottled water display near the entrance so people can find it easily.","Chị Newton đã làm rồi. Và tôi sẽ dời kệ nước đóng chai ra gần lối vào để mọi người dễ tìm."]],"qs":[{"n":32,"q":"Where do the speakers work?","qvi":"Những người nói làm việc ở đâu?","opts":["At a factory","At a grocery store","At a music studio","At a coffee shop"],"vi":["Ở nhà máy","Ở cửa hàng tạp hóa","Ở phòng thu âm","Ở quán cà phê"],"ans":"B","xp":"'our supermarket is the only one in the neighborhood' → supermarket = grocery store → (B)."},{"n":33,"q":"According to the woman, why will the business be busy today?","qvi":"Theo người phụ nữ, vì sao hôm nay cửa hàng sẽ đông?","opts":["Some celebrities will visit the business.","Some items are currently on sale.","An event will be held in the neighborhood.","A competitor has recently closed."],"vi":["Người nổi tiếng sẽ ghé.","Một số hàng đang giảm giá.","Có sự kiện trong khu vực.","Đối thủ vừa đóng cửa."],"ans":"C","xp":"'there's a music festival at Mathis Park today... a lot of people will be stopping by' → (C)."},{"n":34,"q":"What does the woman say she will do?","qvi":"Người phụ nữ nói sẽ làm gì?","opts":["Unlock an entrance","Move a display","Return some items","Call a coworker"],"vi":["Mở khóa cửa","Dời kệ trưng bày","Trả lại hàng","Gọi đồng nghiệp"],"ans":"B","xp":"'I'll move the bottled water display near the entrance' → (B). (D) chị Newton đã gọi rồi."}],"a":"XC-T09-32-34.mp3"},{"ns":[35,37],"script":[["W","Good morning. I'm interested in having some business cards printed. Can your business handle that?","Chào buổi sáng. Tôi muốn in một ít danh thiếp. Bên anh làm được không?"],["M","Of course! You just have to provide the text and any logo or graphics you'd like. Then, I'll send you the sample design by e-mail so you can approve it.","Tất nhiên! Chị chỉ cần cung cấp nội dung chữ và logo hay hình ảnh chị muốn. Sau đó tôi sẽ gửi mẫu thiết kế qua e-mail để chị duyệt."],["W","That sounds perfect! The cards are for a new staff member who starts work on July 7. Will they be ready by then?","Tuyệt quá! Danh thiếp này dành cho một nhân viên mới bắt đầu làm việc ngày 7 tháng 7. Kịp không anh?"],["M","Certainly! If you send me the information today, I can have them done by tomorrow afternoon.","Chắc chắn! Nếu chị gửi thông tin hôm nay, chiều mai tôi làm xong."]],"qs":[{"n":35,"q":"What is the conversation mainly about?","qvi":"Cuộc hội thoại chủ yếu về điều gì?","opts":["Upgrading a Web site","Printing business cards","Moving to a new office","Getting a business loan"],"vi":["Nâng cấp trang web","In danh thiếp","Chuyển văn phòng mới","Vay vốn kinh doanh"],"ans":"B","xp":"'I'm interested in having some business cards printed' → (B)."},{"n":36,"q":"Why will the man send an e-mail to the woman?","qvi":"Vì sao người đàn ông sẽ gửi e-mail cho người phụ nữ?","opts":["To show past clients' projects","To recommend a product","To request a payment","To confirm a design"],"vi":["Để cho xem dự án của khách cũ","Để giới thiệu sản phẩm","Để yêu cầu thanh toán","Để xác nhận thiết kế"],"ans":"D","xp":"'I'll send you the sample design by e-mail so you can approve it' → để chị duyệt thiết kế → (D)."},{"n":37,"q":"According to the woman, what will happen on July 7?","qvi":"Theo người phụ nữ, ngày 7 tháng 7 sẽ có chuyện gì?","opts":["A new employee will begin work.","A price for a service will increase.","A business will have a grand opening.","An office will close earlier than usual."],"vi":["Một nhân viên mới bắt đầu làm việc.","Giá dịch vụ sẽ tăng.","Một doanh nghiệp khai trương.","Văn phòng đóng cửa sớm hơn."],"ans":"A","xp":"'a new staff member who starts work on July 7' → (A)."}],"a":"XC-T09-35-37.mp3"},{"ns":[38,40],"script":[["W1","James and Patricia, thanks for assisting with the open house for the property on Camden Street. This is an important client for our real estate firm. It's too bad that so few people attended the open house, though.","James và Patricia, cảm ơn hai bạn đã hỗ trợ buổi mở cửa cho khách xem căn nhà trên phố Camden. Đây là khách hàng quan trọng của công ty bất động sản mình. Tiếc là có quá ít người đến xem nhà."],["M","Yeah, the small number of visitors was a letdown.","Ừ, lượng khách ít quá thật đáng thất vọng."],["W2","Well, we can feature the property on our Web site to give it more exposure.","À, mình có thể đăng căn nhà lên trang web để nhiều người biết hơn."],["W1","Good point, Patricia. Could you go to the house today and take more pictures of it? That would be good for the online listing.","Ý hay đấy, Patricia. Hôm nay bạn đến căn nhà chụp thêm ảnh được không? Như vậy sẽ tốt cho tin đăng trên mạng."]],"qs":[{"n":38,"q":"What kind of business do the speakers work for?","qvi":"Những người nói làm cho loại doanh nghiệp nào?","opts":["A real estate agency","A financial institution","A construction company","A post office"],"vi":["Công ty bất động sản","Tổ chức tài chính","Công ty xây dựng","Bưu điện"],"ans":"A","xp":"'our real estate firm' → (A)."},{"n":39,"q":"What were the speakers disappointed by?","qvi":"Họ thất vọng về điều gì?","opts":["Low attendance at an event","Problems with a supply order","Negative customer comments","A lack of qualified employees"],"vi":["Ít người tham dự sự kiện","Vấn đề với đơn đặt hàng","Bình luận xấu của khách","Thiếu nhân viên có năng lực"],"ans":"A","xp":"'so few people attended the open house' – 'the small number of visitors was a letdown' → (A)."},{"n":40,"q":"What is Patricia asked to do?","qvi":"Patricia được nhờ làm gì?","opts":["Organize a meeting","Contact a customer","Visit a Web site","Take some photographs"],"vi":["Tổ chức cuộc họp","Liên hệ khách hàng","Vào một trang web","Chụp ảnh"],"ans":"D","xp":"'Patricia. Could you go to the house today and take more pictures of it?' → (D)."}],"a":"XC-T09-38-40.mp3"},{"ns":[41,43],"script":[["M","The open interviews for the positions at our firm will be held on Thursday. Are there any more preparations that need to be made?","Buổi phỏng vấn mở cho các vị trí ở công ty mình sẽ diễn ra vào thứ Năm. Còn cần chuẩn bị gì thêm không?"],["W","We've advertised heavily, so we expect a great turnout. Some of our HR employees will be conducting on-the-spot interviews. I've made a schedule for the times they'll cover. I'll print out duplicates tomorrow.","Mình đã quảng cáo rất nhiều nên dự kiến sẽ có đông người đến. Vài nhân viên nhân sự sẽ phỏng vấn tại chỗ. Tôi đã lập lịch các khung giờ họ phụ trách. Mai tôi sẽ in thêm bản sao."],["M","Great. Can I help you with anything?","Tốt lắm. Tôi giúp được gì không?"],["W","Well, last year we conducted several interviews at once in the main hall. It was a bit noisy, wasn't it?","À, năm ngoái mình phỏng vấn nhiều người cùng lúc ở hội trường chính. Hơi ồn, phải không?"],["M","Yes, it was. Why don't we reserve smaller meeting rooms so that the interviews can be private? I'll take care of that.","Đúng vậy. Sao mình không đặt các phòng họp nhỏ hơn để phỏng vấn riêng tư? Tôi sẽ lo việc đó."]],"qs":[{"n":41,"q":"What is the conversation mainly about?","qvi":"Cuộc hội thoại chủ yếu về điều gì?","opts":["Some travel arrangements","A recruitment effort","A renovation project","A training session"],"vi":["Sắp xếp chuyến đi","Đợt tuyển dụng","Dự án cải tạo","Buổi đào tạo"],"ans":"B","xp":"'The open interviews for the positions at our firm' → tuyển dụng → (B)."},{"n":42,"q":"What does the woman plan to do tomorrow?","qvi":"Ngày mai người phụ nữ định làm gì?","opts":["Print copies of a schedule","Set up some equipment","Post an advertisement","Give a presentation"],"vi":["In bản sao lịch trình","Lắp đặt thiết bị","Đăng quảng cáo","Thuyết trình"],"ans":"A","xp":"'I've made a schedule... I'll print out duplicates tomorrow' → (A)."},{"n":43,"q":"What does the man recommend doing?","qvi":"Người đàn ông đề xuất làm gì?","opts":["Making repairs to a sound system","Postponing an industry event","Creating online materials","Booking meeting spaces"],"vi":["Sửa hệ thống âm thanh","Hoãn sự kiện ngành","Tạo tài liệu trực tuyến","Đặt phòng họp"],"ans":"D","xp":"'Why don't we reserve smaller meeting rooms...?' → (D)."}],"a":"XC-T09-41-43.mp3"},{"ns":[44,46],"script":[["M","Good afternoon. I saw in the newspaper that your business is having a sale. I'd like to buy a sapphire necklace.","Chào buổi chiều. Tôi thấy trên báo cửa hàng đang giảm giá. Tôi muốn mua một sợi dây chuyền đá sapphire."],["W","If the display case is empty, it means we're sold out. We'll get a new shipment on Tuesday, though.","Nếu tủ trưng bày trống thì có nghĩa là đã bán hết. Nhưng thứ Ba sẽ có hàng mới về."],["M","Well, I was planning to buy it as a birthday gift. The celebration is this evening.","À, tôi định mua làm quà sinh nhật. Tiệc là tối nay rồi."],["W","We have a wide range of necklaces with other precious gems. I'm sure you could find something you like.","Chúng tôi có nhiều loại dây chuyền đính đá quý khác. Chắc chắn anh sẽ tìm được cái ưng ý."],["M","Hmm... I really need the sapphire one so that it matches some other accessories my friend has. Would you mind looking in the stock room just to make sure?","Hừm... Tôi thật sự cần cái sapphire để hợp với phụ kiện khác của bạn tôi. Chị xem giúp trong kho cho chắc được không?"]],"qs":[{"n":44,"q":"Where does the woman most likely work?","qvi":"Người phụ nữ nhiều khả năng làm ở đâu?","opts":["At a fashion magazine firm","At a courier service","At a newspaper publisher","At a jewelry store"],"vi":["Ở tạp chí thời trang","Ở dịch vụ chuyển phát","Ở nhà xuất bản báo","Ở cửa hàng trang sức"],"ans":"D","xp":"Khách muốn mua 'a sapphire necklace', cô nói về tủ trưng bày, hàng mới về → cửa hàng trang sức → (D). (C) lặp từ newspaper."},{"n":45,"q":"What does the man suggest when he says, \"The celebration is this evening\"?","qvi":"Người đàn ông ngụ ý gì khi nói \"Tiệc là tối nay rồi\"?","opts":["He cannot put off making a purchase.","He wants to postpone the event.","He needs to correct a scheduling error.","He is inviting the woman to a party."],"vi":["Ông không thể hoãn việc mua.","Ông muốn hoãn sự kiện.","Ông cần sửa lỗi lịch.","Ông mời cô đến tiệc."],"ans":"A","xp":"Cô nói thứ Ba mới có hàng; ông đáp tiệc là tối nay → không đợi đến thứ Ba được, phải mua ngay → (A)."},{"n":46,"q":"What does the man ask the woman to do?","qvi":"Người đàn ông nhờ người phụ nữ làm gì?","opts":["Bring over a manager","Check a storage area","Call a different branch","Place an order online"],"vi":["Gọi quản lý đến","Kiểm tra kho","Gọi chi nhánh khác","Đặt hàng trên mạng"],"ans":"B","xp":"'Would you mind looking in the stock room...?' → stock room = storage area → (B)."}],"a":"XC-T09-44-46.mp3"},{"ns":[47,49],"script":[["M","Ms. Meisner, thanks for taking the time to give me a tour of your facility.","Chị Meisner, cảm ơn chị đã dành thời gian dẫn tôi tham quan cơ sở."],["W","It's my pleasure. I think our concert hall would be perfect for your orchestra's annual show. I know that you held it at the Pelham Center last year. May I ask why you decided to make a change?","Rất hân hạnh. Tôi nghĩ phòng hòa nhạc của chúng tôi sẽ rất hợp cho buổi diễn thường niên của dàn nhạc anh. Tôi biết năm ngoái anh tổ chức ở Trung tâm Pelham. Cho tôi hỏi vì sao anh quyết định đổi?"],["M","Well, the seating capacity there was too low. There were a lot of people who were unable to get tickets.","À, sức chứa chỗ ngồi ở đó quá ít. Rất nhiều người không mua được vé."],["W","I understand. That definitely won't be a problem here.","Tôi hiểu. Ở đây chắc chắn sẽ không gặp vấn đề đó."],["M","Wonderful. We'll go with your site. How soon could you draw up the contract?","Tuyệt. Chúng tôi chọn chỗ của chị. Chị soạn hợp đồng nhanh nhất là bao lâu?"],["W","It'll take three days to prepare it. I'll send it to you as soon as it's ready.","Mất ba ngày để chuẩn bị. Xong là tôi gửi anh ngay."]],"qs":[{"n":47,"q":"Where does the woman work?","qvi":"Người phụ nữ làm việc ở đâu?","opts":["At a recording studio","At a sports arena","At a concert hall","At a radio station"],"vi":["Ở phòng thu âm","Ở sân vận động","Ở phòng hòa nhạc","Ở đài phát thanh"],"ans":"C","xp":"'I think our concert hall would be perfect' → (C)."},{"n":48,"q":"According to the man, what was the problem last year?","qvi":"Theo người đàn ông, năm ngoái có vấn đề gì?","opts":["There were not enough seats.","The staff was unprofessional.","Some ticket machines malfunctioned.","There was a scheduling conflict."],"vi":["Không đủ chỗ ngồi.","Nhân viên thiếu chuyên nghiệp.","Máy bán vé hỏng.","Bị trùng lịch."],"ans":"A","xp":"'the seating capacity there was too low' → (A)."},{"n":49,"q":"What will the woman send to the man in three days?","qvi":"Ba ngày nữa người phụ nữ sẽ gửi gì?","opts":["A contract","A pamphlet","A map","An invoice"],"vi":["Hợp đồng","Tờ rơi","Bản đồ","Hóa đơn"],"ans":"A","xp":"'How soon could you draw up the contract?' – 'It'll take three days... I'll send it to you' → (A)."}],"a":"XC-T09-47-49.mp3"},{"ns":[50,52],"script":[["M","Tessa, I want you to design some brochures for Griffin Furniture. They have some new mattresses and bed frames that they want to inform their customers about.","Tessa, tôi muốn chị thiết kế vài tờ quảng cáo cho Griffin Furniture. Họ có nệm và khung giường mới muốn giới thiệu với khách hàng."],["W","No problem. I've worked closely with Griffin Furniture for a long time, so I know their needs well.","Không vấn đề gì. Tôi đã làm việc sát với Griffin Furniture lâu rồi nên hiểu rõ nhu cầu của họ."],["M","I know. That's why I thought you'd be the right person for this project. The work needs to be completed by the day after tomorrow.","Tôi biết. Vì vậy tôi nghĩ chị là người phù hợp cho dự án này. Việc này cần xong trước ngày kia."],["W","That's soon. You know, I'm supposed to be working on some business cards for Lowry Co.","Gấp thế. Anh biết đấy, tôi còn đang phải làm danh thiếp cho công ty Lowry."],["M","Why don't you pass that duty on to Gina? The Griffin Furniture project is much more important, so I want you to give it your full attention.","Sao chị không giao việc đó cho Gina? Dự án Griffin Furniture quan trọng hơn nhiều, nên tôi muốn chị tập trung toàn bộ vào nó."]],"qs":[{"n":50,"q":"Where is the conversation most likely taking place?","qvi":"Cuộc hội thoại nhiều khả năng diễn ra ở đâu?","opts":["At a furniture store","At a graphic design company","At a city park","At a museum"],"vi":["Ở cửa hàng nội thất","Ở công ty thiết kế đồ họa","Ở công viên","Ở bảo tàng"],"ans":"B","xp":"Họ thiết kế tờ quảng cáo, danh thiếp cho khách hàng → công ty thiết kế đồ họa → (B). (A) Griffin Furniture là khách hàng, không phải nơi họ làm."},{"n":51,"q":"According to the man, why did he want to assign the task to the woman?","qvi":"Theo người đàn ông, vì sao ông muốn giao việc cho người phụ nữ?","opts":["She is familiar with a client.","She is able to work additional hours.","She has completed similar projects before.","She has experience leading a team."],"vi":["Cô hiểu rõ khách hàng.","Cô có thể làm thêm giờ.","Cô từng làm dự án tương tự.","Cô có kinh nghiệm dẫn dắt nhóm."],"ans":"A","xp":"Cô nói 'I've worked closely with Griffin Furniture... I know their needs well' – ông đáp 'That's why...' → (A)."},{"n":52,"q":"What does the man think the woman should do?","qvi":"Người đàn ông nghĩ người phụ nữ nên làm gì?","opts":["Pick up some supplies from Gina","Complete a request form","Delegate a project to a coworker","Meet a client in person"],"vi":["Lấy vật tư từ Gina","Điền phiếu yêu cầu","Giao bớt việc cho đồng nghiệp","Gặp trực tiếp khách hàng"],"ans":"C","xp":"'Why don't you pass that duty on to Gina?' → giao việc cho đồng nghiệp → (C)."}],"a":"XC-T09-50-52.mp3"},{"ns":[53,55],"script":[["W","You've reached Ollie Commercial Kitchen Supplies. How may I help you?","Đây là Ollie, chuyên đồ dùng bếp thương mại. Tôi giúp gì được ạ?"],["M","Hello. I bought an oven for my bake shop last week, but it's not working like I expected.","Xin chào. Tuần trước tôi mua một lò nướng cho tiệm bánh của tôi, nhưng nó không chạy như tôi mong đợi."],["W","What seems to be the problem?","Có vấn đề gì vậy ạ?"],["M","Well, the oven is not shutting off on its own after the timer goes off. I've already burned several batches of bread.","À, lò không tự tắt khi hết giờ hẹn. Tôi đã làm cháy mấy mẻ bánh mì rồi."],["W","I'm very sorry for the inconvenience, sir. Have you tried resetting the oven? That usually solves the problem.","Thành thật xin lỗi vì sự bất tiện. Anh đã thử cài đặt lại lò chưa? Thường làm vậy là hết lỗi."],["M","Hmm, I'm not sure how to do that.","Hừm, tôi không biết làm thế nào."],["W","It's difficult to explain over the phone, but take a look at the manual that came with the device. Those instructions should be clear.","Khó giải thích qua điện thoại, nhưng anh hãy xem sách hướng dẫn kèm theo máy. Hướng dẫn trong đó khá rõ."]],"qs":[{"n":53,"q":"What business does the man operate?","qvi":"Người đàn ông kinh doanh gì?","opts":["A supermarket","A bakery","A repair shop","An electronics store"],"vi":["Siêu thị","Tiệm bánh","Tiệm sửa chữa","Cửa hàng điện tử"],"ans":"B","xp":"'an oven for my bake shop' → (B)."},{"n":54,"q":"According to the man, what is the problem with a product?","qvi":"Theo người đàn ông, sản phẩm có vấn đề gì?","opts":["It does not turn off automatically.","Its alarm is too quiet to hear.","It does not heat up quickly enough.","It has a cracked display screen."],"vi":["Không tự tắt.","Chuông báo quá nhỏ.","Nóng lên không đủ nhanh.","Màn hình bị nứt."],"ans":"A","xp":"'the oven is not shutting off on its own' → (A)."},{"n":55,"q":"What does the woman instruct the man to do?","qvi":"Người phụ nữ hướng dẫn người đàn ông làm gì?","opts":["Unplug the equipment","Clean off a sensor","Read a user manual","Watch an online tutorial"],"vi":["Rút phích cắm","Lau cảm biến","Đọc sách hướng dẫn","Xem video hướng dẫn trên mạng"],"ans":"C","xp":"'take a look at the manual that came with the device' → (C)."}],"a":"XC-T09-53-55.mp3"},{"ns":[56,58],"script":[["W1","Veronica, we've got to finish up the work here at Arcadia Co.'s offices before moving on to the public library.","Veronica, mình phải làm xong việc ở văn phòng công ty Arcadia rồi mới chuyển sang thư viện công cộng."],["W2","Okay. I just have one floor of windows left to clean. Max, would you meet me on the third floor to work on them with me?","Được. Tôi chỉ còn một tầng cửa sổ phải lau. Max, anh lên tầng ba lau cùng tôi được không?"],["M","The carpets didn't get clean after passing the steam cleaner over them just once. They need a second run.","Thảm chưa sạch sau một lượt máy giặt hơi nước. Phải chạy thêm lượt nữa."],["W2","All right, then I'll take care of the rest of the windows myself.","Được rồi, vậy tôi tự lau chỗ cửa sổ còn lại."],["W1","And don't forget that the truck's going to be here at eight thirty to pick up the dumpster. So, let's get back together at eight o'clock to empty all of the garbage bins.","Và đừng quên 8 giờ 30 xe tải sẽ đến lấy thùng rác lớn. Vậy 8 giờ mình tập trung lại để đổ hết các thùng rác."],["M","Sounds great.","Được đấy."]],"qs":[{"n":56,"q":"Where is the conversation taking place?","qvi":"Cuộc hội thoại diễn ra ở đâu?","opts":["At an appliances store","At a public library","At a manufacturing facility","At a commercial building"],"vi":["Ở cửa hàng đồ gia dụng","Ở thư viện công cộng","Ở nhà máy","Ở tòa nhà văn phòng"],"ans":"D","xp":"'finish up the work here at Arcadia Co.'s offices' → tòa nhà văn phòng → (D). (B) là nơi họ sẽ đến sau."},{"n":57,"q":"Why does the man say, \"They need a second run\"?","qvi":"Vì sao người đàn ông nói \"Phải chạy thêm lượt nữa\"?","opts":["To apologize for a lack of space","To explain why he cannot help","To complain about a colleague's work","To request a rush order"],"vi":["Để xin lỗi vì thiếu chỗ","Để giải thích vì sao không giúp được","Để phàn nàn về việc của đồng nghiệp","Để yêu cầu đơn gấp"],"ans":"B","xp":"Veronica nhờ Max lên lau cửa sổ cùng; Max nói thảm còn phải giặt thêm lượt nữa → ông còn bận, không giúp được; Veronica đáp 'I'll take care of the rest myself' → (B)."},{"n":58,"q":"What do the speakers plan to do at eight o'clock?","qvi":"Lúc 8 giờ họ định làm gì?","opts":["Assign some new tasks","Ride together in a truck","Take a break","Empty some trash containers"],"vi":["Giao việc mới","Đi chung xe tải","Nghỉ giải lao","Đổ thùng rác"],"ans":"D","xp":"'let's get back together at eight o'clock to empty all of the garbage bins' → (D). (B) xe tải đến lúc 8:30 để lấy thùng rác."}],"a":"XC-T09-56-58.mp3"},{"ns":[59,61],"script":[["W","Louis, our CEO wants to transition from print copies to online editions for the magazines we publish. More and more people are using smartphones to consume information, so this will better position our company for the future.","Louis, giám đốc muốn chuyển các tạp chí mình xuất bản từ bản in sang bản trực tuyến. Ngày càng nhiều người dùng điện thoại để đọc thông tin, nên điều này sẽ giúp công ty chuẩn bị tốt hơn cho tương lai."],["M","That makes sense, but I don't think our current staff can handle a project like that at the moment. We'll need a lot more people to do the work properly.","Hợp lý, nhưng tôi không nghĩ đội ngũ hiện tại làm nổi dự án như vậy lúc này. Mình sẽ cần thêm nhiều người mới làm tốt được."],["W","Well, there's going to be a recruiting expo in Toronto in May. Maybe our company could have a booth there to hire the new employees we need.","À, tháng 5 sẽ có hội chợ tuyển dụng ở Toronto. Có lẽ công ty mình nên đặt gian hàng ở đó để tuyển người mới."]],"qs":[{"n":59,"q":"What industry do the speakers work in?","qvi":"Những người nói làm trong ngành nào?","opts":["Publishing","Finance","Manufacturing","Education"],"vi":["Xuất bản","Tài chính","Sản xuất","Giáo dục"],"ans":"A","xp":"'the magazines we publish' → xuất bản → (A)."},{"n":60,"q":"Why is the man worried?","qvi":"Vì sao người đàn ông lo lắng?","opts":["Government regulations are not met.","The prices are too expensive.","Some materials are harmful.","The company is understaffed."],"vi":["Chưa đáp ứng quy định nhà nước.","Giá quá đắt.","Một số vật liệu có hại.","Công ty thiếu người."],"ans":"D","xp":"'I don't think our current staff can handle... We'll need a lot more people' → thiếu người → (D)."},{"n":61,"q":"What event will take place in Toronto in May?","qvi":"Sự kiện nào diễn ra ở Toronto vào tháng 5?","opts":["A press conference","A job fair","A company anniversary","A sports competition"],"vi":["Họp báo","Hội chợ việc làm","Lễ kỷ niệm công ty","Cuộc thi thể thao"],"ans":"B","xp":"'a recruiting expo in Toronto in May' → recruiting expo = job fair → (B)."}],"a":"XC-T09-59-61.mp3"},{"ns":[62,64],"script":[["M","Hello. I'm planning to move to the Fairmont neighborhood next month so that I don't have to commute so far to my office. I need a one-bedroom apartment.","Xin chào. Tôi định chuyển đến khu Fairmont tháng sau để không phải đi làm xa nữa. Tôi cần căn hộ một phòng ngủ."],["W","I can help you with that. These apartments here are available for move-in next month.","Tôi giúp anh được. Những căn hộ này có thể dọn vào tháng sau."],["M","Hmm, I think this studio would be too small for me.","Hừm, tôi nghĩ căn studio này quá nhỏ với tôi."],["W","Yes, it's only about six hundred square feet.","Vâng, nó chỉ khoảng 600 feet vuông."],["M","Well, I have a budget of seven hundred dollars per month.","À, ngân sách của tôi là 700 đô la mỗi tháng."],["W","You can see here that we have a one-bedroom apartment that's six hundred seventy-five dollars per month. It's in a new building, too.","Anh xem, ở đây có căn một phòng ngủ giá 675 đô la mỗi tháng. Lại ở tòa nhà mới nữa."],["M","Wonderful. I'd like to tour the property as soon as possible.","Tuyệt. Tôi muốn đi xem nhà càng sớm càng tốt."],["W","Let me reserve the next available time slot for you.","Để tôi đặt khung giờ trống gần nhất cho anh."]],"qs":[{"n":62,"q":"Why does the man plan to move to the Fairmont neighborhood?","qvi":"Vì sao người đàn ông định chuyển đến khu Fairmont?","opts":["He will start a new business.","He will transfer to a new job.","He wants to be closer to work.","He wants to live with his family."],"vi":["Ông sẽ mở công ty mới.","Ông sẽ chuyển công tác.","Ông muốn ở gần chỗ làm.","Ông muốn sống với gia đình."],"ans":"C","xp":"'so that I don't have to commute so far to my office' → (C)."},{"n":63,"q":"Look at the graphic. Which building has an apartment that the man is interested in?","qvi":"Nhìn hình. Tòa nhà nào có căn hộ người đàn ông quan tâm?","opts":["Max Tower","Westway Apartments","Emerson Suites","Springview"],"vi":["Max Tower","Westway Apartments","Emerson Suites","Springview"],"ans":"C","xp":"Ông cần căn một phòng ngủ, ngân sách 700 đô; cô giới thiệu căn 675 đô; bảng: Emerson Suites – One-bedroom: $675/month → (C). (B) Westway $750 vượt ngân sách."},{"n":64,"q":"What will the woman most likely do next?","qvi":"Người phụ nữ nhiều khả năng sẽ làm gì tiếp theo?","opts":["Download a map","Print a receipt","Sign a contract","Book a tour"],"vi":["Tải bản đồ","In biên lai","Ký hợp đồng","Đặt lịch xem nhà"],"ans":"D","xp":"'I'd like to tour the property' – 'Let me reserve the next available time slot for you' → (D)."}],"a":"XC-T09-62-64.mp3","img":"g62.png"},{"ns":[65,67],"script":[["M","Christina, have you written the description of our business for the Lindenberg Guidebook yet? We need to submit it today so that our facility will be listed.","Christina, chị đã viết phần giới thiệu doanh nghiệp mình cho cuốn Cẩm nang Lindenberg chưa? Hôm nay phải nộp thì cơ sở mình mới được đưa vào danh sách."],["W","Yes, I've just finished a draft that you can look over. I've outlined the equipment and classes that we offer at our gym. There's also information about how to get a one-day pass, which I think will be of interest to tourists.","Rồi, tôi vừa viết xong bản nháp để anh xem. Tôi đã nêu các thiết bị và lớp học ở phòng tập của mình. Còn có thông tin về cách mua vé tập một ngày, tôi nghĩ khách du lịch sẽ quan tâm."],["M","That's perfect. This will be great publicity for us, because the guidebook goes out to 95 percent of the hotels in the area and all of the tourist centers and travel agencies.","Tuyệt quá. Đây sẽ là cách quảng bá rất tốt cho mình, vì cuốn cẩm nang được phát đến 95% khách sạn trong khu vực và tất cả trung tâm du lịch, công ty lữ hành."]],"qs":[{"n":65,"q":"What task has the woman been assigned?","qvi":"Người phụ nữ được giao việc gì?","opts":["Preparing photos of a site","Writing a company description","Making updates to a Web site","Researching some tourist activities"],"vi":["Chuẩn bị ảnh địa điểm","Viết phần giới thiệu công ty","Cập nhật trang web","Tìm hiểu hoạt động du lịch"],"ans":"B","xp":"'have you written the description of our business...?' – 'I've just finished a draft' → (B)."},{"n":66,"q":"Look at the graphic. In which section would the speakers' business most likely appear?","qvi":"Nhìn hình. Doanh nghiệp của họ nhiều khả năng xuất hiện ở mục nào?","opts":["Section A","Section B","Section C","Section D"],"vi":["Mục A","Mục B","Mục C","Mục D"],"ans":"D","xp":"'the equipment and classes that we offer at our gym' → phòng tập; bảng: Section D – Health and Fitness → (D)."},{"n":67,"q":"What benefit of the guidebook does the man mention?","qvi":"Người đàn ông nhắc đến lợi ích nào của cuốn cẩm nang?","opts":["It has many discount offers.","It has a wide distribution network.","It offers a space for free advertisements.","It is updated every other week."],"vi":["Có nhiều ưu đãi giảm giá.","Được phát hành rộng rãi.","Có chỗ quảng cáo miễn phí.","Cập nhật hai tuần một lần."],"ans":"B","xp":"'the guidebook goes out to 95 percent of the hotels... and all of the tourist centers and travel agencies' → phát hành rộng → (B)."}],"a":"XC-T09-65-67.mp3","img":"g65.png"},{"ns":[68,70],"script":[["M","Hi, Debbie. It's Colin. I'm really sorry, but I'm going to be late for the dinner with our new client, Mr. Porter. My car wouldn't start, so I had to take the bus instead.","Chào Debbie, Colin đây. Tôi rất xin lỗi nhưng tôi sẽ đến muộn bữa tối với khách hàng mới, ông Porter. Xe tôi không nổ máy nên tôi phải đi xe buýt."],["W","Oh, I see. The reservation is at seven at Willow's Steakhouse, right?","À, tôi hiểu rồi. Bàn đặt lúc 7 giờ ở nhà hàng Willow's Steakhouse, phải không?"],["M","Yes, that's right. It's in Perkins Plaza. I don't want Mr. Porter to be waiting at the restaurant, though. Could you meet him there and welcome him?","Đúng rồi. Ở Perkins Plaza. Nhưng tôi không muốn ông Porter phải đợi ở nhà hàng. Chị có thể gặp và đón tiếp ông ấy được không?"],["W","Of course. How late do you think you'll be?","Tất nhiên. Anh nghĩ sẽ muộn bao lâu?"],["M","Hmm... we're passing the Odell Mall right now, so it'll be about thirty minutes.","Hừm... bây giờ xe đang đi qua trung tâm thương mại Odell, nên khoảng 30 phút nữa."],["W","All right. We'll order some appetizers in the meantime.","Được rồi. Trong lúc đó chúng tôi sẽ gọi món khai vị."]],"qs":[{"n":68,"q":"What problem does the man mention?","qvi":"Người đàn ông nêu vấn đề gì?","opts":["His reservation was canceled.","His meeting ran late.","He took the wrong bus.","He had car trouble."],"vi":["Đặt chỗ bị hủy.","Cuộc họp kéo dài.","Ông đi nhầm xe buýt.","Xe ông bị trục trặc."],"ans":"D","xp":"'My car wouldn't start' → (D). (C) ông đi xe buýt nhưng không nhầm xe."},{"n":69,"q":"What is the woman asked to do?","qvi":"Người phụ nữ được nhờ làm gì?","opts":["Greet a client","Approve an expense","Reserve a rental car","Set up a screen"],"vi":["Đón tiếp khách hàng","Duyệt khoản chi","Đặt thuê xe","Lắp màn hình"],"ans":"A","xp":"'Could you meet him there and welcome him?' → (A)."},{"n":70,"q":"Look at the graphic. Where is the man near now?","qvi":"Nhìn hình. Bây giờ người đàn ông đang ở gần đâu?","opts":["Elmhurst Street","Hartford Street","Caldwell Street","Austin Street"],"vi":["Phố Elmhurst","Phố Hartford","Phố Caldwell","Phố Austin"],"ans":"A","xp":"'we're passing the Odell Mall right now'; trên bản đồ, trạm gần Odell Mall nhất là Elmhurst Street → (A)."}],"a":"XC-T09-68-70.mp3","img":"g68.png"}],"p4":[{"ns":[71,73],"script":[["","Thank you all for coming to this staff meeting. With the summer holidays approaching, we're expecting a lot more daytime visitors to our library. Next month will be the start of our youth literacy program. We want to get more children and teenagers interested in reading. The book club meetings for this event are currently supposed to last two hours. I think this is a bit too long, so I suggest changing them to one hour. I'll explain my reasons for this. While I'm doing so, please make sure you sign the attendance sheet that I'm passing around.","Cảm ơn mọi người đã đến buổi họp nhân viên. Kỳ nghỉ hè sắp đến, chúng ta dự kiến thư viện sẽ có nhiều khách ban ngày hơn. Tháng sau sẽ bắt đầu chương trình đọc viết cho thanh thiếu niên. Chúng ta muốn trẻ em và thiếu niên hứng thú với việc đọc hơn. Hiện các buổi câu lạc bộ sách của chương trình dự kiến kéo dài hai tiếng. Tôi nghĩ hơi dài, nên tôi đề xuất rút xuống một tiếng. Tôi sẽ giải thích lý do. Trong lúc đó, mọi người nhớ ký vào tờ điểm danh tôi đang chuyền đi."]],"qs":[{"n":71,"q":"What is the speaker mainly discussing?","qvi":"Người nói chủ yếu bàn về điều gì?","opts":["A construction project","A reading program","A VIP visitor","A budget surplus"],"vi":["Dự án xây dựng","Chương trình đọc sách","Khách VIP","Ngân sách dư"],"ans":"B","xp":"'our youth literacy program. We want to get more children and teenagers interested in reading' → (B)."},{"n":72,"q":"What does the speaker suggest changing?","qvi":"Người nói đề xuất thay đổi điều gì?","opts":["The duration of an event","The promotional method","The location of a class","The number of volunteers"],"vi":["Thời lượng sự kiện","Cách quảng bá","Địa điểm lớp học","Số tình nguyện viên"],"ans":"A","xp":"'supposed to last two hours... I suggest changing them to one hour' → thời lượng → (A)."},{"n":73,"q":"What are the listeners asked to do?","qvi":"Người nghe được yêu cầu làm gì?","opts":["Sign a form","Share some feedback","Take notes","E-mail some information"],"vi":["Ký vào một tờ giấy","Góp ý","Ghi chép","E-mail thông tin"],"ans":"A","xp":"'please make sure you sign the attendance sheet' → (A)."}],"a":"XC-T09-71-73.mp3"},{"ns":[74,76],"script":[["","Hi, Mr. Coulter. This is Maria from the property management office. The resurfacing project for the apartment building's lot will not be finished today as previously announced. I told the construction company that we had forty spots, but it's actually sixty, so they didn't bring enough materials. I'm sorry about that issue. You won't be able to use the lot until Saturday morning. I've got a temporary street parking pass for you here at the office, so please come pick it up.","Chào ông Coulter. Tôi là Maria ở văn phòng quản lý tòa nhà. Dự án làm lại mặt bãi đỗ xe của tòa chung cư sẽ không xong hôm nay như đã thông báo. Tôi đã báo với công ty xây dựng là bãi có 40 chỗ, nhưng thực ra là 60, nên họ không mang đủ vật liệu. Tôi xin lỗi về chuyện đó. Ông sẽ chưa dùng được bãi xe cho đến sáng thứ Bảy. Tôi có sẵn thẻ đỗ xe tạm thời trên đường cho ông ở văn phòng, ông hãy đến lấy nhé."]],"qs":[{"n":74,"q":"What does the speaker say has been delayed?","qvi":"Người nói cho biết việc gì bị chậm?","opts":["The installation of security equipment","The renewal of an apartment lease","The repaving of a parking lot","The tour of an apartment building"],"vi":["Lắp thiết bị an ninh","Gia hạn hợp đồng thuê","Làm lại mặt bãi đỗ xe","Tham quan tòa chung cư"],"ans":"C","xp":"'The resurfacing project for the apartment building's lot will not be finished today' → resurfacing = repaving → (C)."},{"n":75,"q":"Why does the speaker make an apology?","qvi":"Vì sao người nói xin lỗi?","opts":["A reservation was given to another tenant.","A company has increased its prices.","She used poor-quality materials.","She provided some incorrect information."],"vi":["Chỗ đặt bị giao cho người thuê khác.","Một công ty tăng giá.","Cô dùng vật liệu kém.","Cô đã đưa thông tin sai."],"ans":"D","xp":"'I told the construction company that we had forty spots, but it's actually sixty... I'm sorry' → (D)."},{"n":76,"q":"What is the listener asked to do?","qvi":"Người nghe được yêu cầu làm gì?","opts":["Pick up a pass","Place an order","Move some items","Approve a schedule"],"vi":["Đến lấy thẻ","Đặt hàng","Dời đồ","Duyệt lịch"],"ans":"A","xp":"'a temporary street parking pass... please come pick it up' → (A)."}],"a":"XC-T09-74-76.mp3"},{"ns":[77,79],"script":[["","Welcome, everyone, to this VIP tour of Tacoma Studios. I hope you have an enjoyable time as you learn about how we produce our movies from start to finish. We'll tour both current and old sets, and you might even see some filming going on. Throughout the tour, please don't hesitate to share your questions. I'll do my best to answer them. Before we begin, however, I'd like you to look over the handout I gave you, which explains our policy regarding what you can and cannot photograph. Since this tour includes a free lunch, I'll be passing out vouchers for our on-site café once the tour is finished, so don't leave without one.","Chào mừng mọi người đến chuyến tham quan VIP của hãng phim Tacoma Studios. Mong mọi người có khoảng thời gian thú vị khi tìm hiểu cách chúng tôi làm phim từ đầu đến cuối. Chúng ta sẽ tham quan cả phim trường đang dùng và phim trường cũ, có khi còn được xem quay phim. Trong suốt chuyến đi, cứ thoải mái đặt câu hỏi. Tôi sẽ cố gắng trả lời. Nhưng trước khi bắt đầu, mọi người hãy đọc qua tờ hướng dẫn tôi đã phát, trong đó giải thích quy định về những gì được chụp và không được chụp. Vì chuyến tham quan có kèm bữa trưa miễn phí, khi kết thúc tôi sẽ phát phiếu ăn ở quán cà phê trong khuôn viên, nên đừng về mà chưa lấy nhé."]],"qs":[{"n":77,"q":"Where does the speaker work?","qvi":"Người nói làm việc ở đâu?","opts":["At a movie production company","At a national park","At a community theater","At a manufacturing facility"],"vi":["Ở công ty sản xuất phim","Ở công viên quốc gia","Ở nhà hát cộng đồng","Ở nhà máy"],"ans":"A","xp":"'Tacoma Studios... how we produce our movies' → (A)."},{"n":78,"q":"According to the speaker, what should the listeners do first?","qvi":"Theo người nói, người nghe nên làm gì trước tiên?","opts":["Go to the information desk","Put on protective gear","Join a membership","Read some information"],"vi":["Đến quầy thông tin","Mặc đồ bảo hộ","Đăng ký hội viên","Đọc thông tin"],"ans":"D","xp":"'Before we begin... look over the handout I gave you' → (D)."},{"n":79,"q":"What does the speaker say the listeners will receive at the end of the tour?","qvi":"Người nói cho biết cuối chuyến tham quan người nghe sẽ nhận gì?","opts":["A feedback form","A meal voucher","Some samples","A partial refund"],"vi":["Phiếu góp ý","Phiếu ăn","Hàng mẫu","Hoàn tiền một phần"],"ans":"B","xp":"'I'll be passing out vouchers for our on-site café once the tour is finished' → phiếu ăn → (B)."}],"a":"XC-T09-77-79.mp3"},{"ns":[80,82],"script":[["","Good afternoon. I'm Sue Miller, and I'd like to thank you for coming to this orientation session. I'll be teaching you all about what to expect from our company in general and your role specifically. To start off, I have some written materials to pass out. A lot of people say that it's better to have you read the policies on your own, but we're going to go through them together. You can get your questions answered right away. After the first two sessions, we'll have a break at four o'clock for coffee and snacks. After that, you'll hear a talk from the company's president.","Chào buổi chiều. Tôi là Sue Miller, cảm ơn mọi người đã đến buổi định hướng cho nhân viên mới. Tôi sẽ hướng dẫn mọi người về công ty nói chung và vai trò cụ thể của từng người. Đầu tiên, tôi có tài liệu phát cho mọi người. Nhiều người nói nên để các bạn tự đọc quy định, nhưng chúng ta sẽ cùng xem qua. Có thắc mắc là được giải đáp ngay. Sau hai phần đầu, 4 giờ chúng ta nghỉ giải lao với cà phê và đồ ăn nhẹ. Sau đó, mọi người sẽ nghe chủ tịch công ty phát biểu."]],"qs":[{"n":80,"q":"Who most likely is the speaker?","qvi":"Người nói nhiều khả năng là ai?","opts":["A job trainer","An author","A company president","A security officer"],"vi":["Người đào tạo nhân viên","Tác giả","Chủ tịch công ty","Nhân viên an ninh"],"ans":"A","xp":"'this orientation session. I'll be teaching you all about... your role' → người đào tạo → (A). (C) chủ tịch là người nói sau."},{"n":81,"q":"Why does the speaker say, \"You can get your questions answered right away\"?","qvi":"Vì sao người nói nói \"Có thắc mắc là được giải đáp ngay\"?","opts":["To recommend a service","To explain a schedule change","To thank her colleagues","To disagree with an opinion"],"vi":["Để giới thiệu dịch vụ","Để giải thích thay đổi lịch","Để cảm ơn đồng nghiệp","Để phản đối một ý kiến"],"ans":"D","xp":"Nhiều người cho rằng nên tự đọc quy định 'but we're going to go through them together' → câu này nêu lý do cô không đồng ý với ý kiến đó → (D)."},{"n":82,"q":"What will take place at 4 P.M.?","qvi":"Lúc 4 giờ chiều sẽ có gì?","opts":["A group photo","A formal speech","A refreshments break","A special election"],"vi":["Chụp ảnh nhóm","Bài phát biểu chính thức","Giờ nghỉ ăn nhẹ","Bầu cử đặc biệt"],"ans":"C","xp":"'we'll have a break at four o'clock for coffee and snacks' → (C). (B) diễn ra sau 4 giờ."}],"a":"XC-T09-80-82.mp3"},{"ns":[83,85],"script":[["","You're listening to Business Time on Radio 89.6 FM. Our guest today is Ayaan Naidu, owner of a successful accounting firm in Oakhurst. His business started with just a few people, but it has grown to a staff of over thirty, and it continues to grow. Mr. Naidu knows firsthand the challenges of managing a business. He's got some great tips on how to make your staff efficient and avoid wasting time. He'll be sharing those with you today. If you have a specific inquiry for Mr. Naidu, be a part of the discussion by e-mailing us through the station's homepage. We look forward to hearing from you.","Bạn đang nghe chương trình Business Time trên Radio 89.6 FM. Khách mời hôm nay là Ayaan Naidu, chủ một công ty kế toán thành công ở Oakhurst. Công ty ông khởi đầu chỉ với vài người, nhưng nay đã hơn 30 nhân viên và vẫn đang phát triển. Ông Naidu hiểu rõ những khó khăn khi điều hành doanh nghiệp. Ông có nhiều mẹo hay giúp nhân viên làm việc hiệu quả và tránh lãng phí thời gian. Hôm nay ông sẽ chia sẻ với các bạn. Nếu có câu hỏi cụ thể cho ông Naidu, hãy tham gia bằng cách gửi e-mail qua trang chủ của đài. Chúng tôi mong nhận được ý kiến của các bạn."]],"qs":[{"n":83,"q":"What kind of business does Mr. Naidu own?","qvi":"Ông Naidu sở hữu loại doanh nghiệp nào?","opts":["An accounting firm","A travel agency","A recruitment firm","A retail shop"],"vi":["Công ty kế toán","Công ty du lịch","Công ty tuyển dụng","Cửa hàng bán lẻ"],"ans":"A","xp":"'owner of a successful accounting firm' → (A)."},{"n":84,"q":"What will Mr. Naidu discuss during the broadcast?","qvi":"Ông Naidu sẽ nói về điều gì trong chương trình?","opts":["Business negotiations","Security measures","Time-saving advice","Market trends"],"vi":["Đàm phán kinh doanh","Biện pháp an ninh","Lời khuyên tiết kiệm thời gian","Xu hướng thị trường"],"ans":"C","xp":"'great tips on how to make your staff efficient and avoid wasting time. He'll be sharing those' → (C)."},{"n":85,"q":"What does the speaker encourage the listeners to do?","qvi":"Người nói khuyến khích người nghe làm gì?","opts":["Call the station","Try a new service","Subscribe to a newsletter","E-mail some questions"],"vi":["Gọi điện đến đài","Dùng thử dịch vụ mới","Đăng ký bản tin","Gửi câu hỏi qua e-mail"],"ans":"D","xp":"'If you have a specific inquiry... e-mailing us through the station's homepage' → (D). (A) gọi điện là sai cách."}],"a":"XC-T09-83-85.mp3"},{"ns":[86,88],"script":[["","Before we open the store, I just want to remind you that we have author Collette Ward coming next week for a book signing event. Be sure to tell shoppers about it and encourage them to attend. We've moved Ms. Ward's latest book to a large display near the checkout area. As for her other novels, we haven't done anything, so you know where they are. Please ignore the work schedule that I e-mailed on June 3. I've made some adjustments due to the event, so I'll be sending a new one later today.","Trước khi mở cửa hàng, tôi muốn nhắc mọi người là tuần sau tác giả Collette Ward sẽ đến buổi ký tặng sách. Nhớ báo cho khách và mời họ tham dự. Chúng ta đã chuyển cuốn sách mới nhất của bà Ward lên kệ trưng bày lớn gần quầy thanh toán. Còn các tiểu thuyết khác của bà thì chúng ta không thay đổi gì, nên mọi người biết chúng ở đâu rồi. Hãy bỏ qua lịch làm việc tôi gửi qua e-mail ngày 3 tháng 6. Tôi đã điều chỉnh vì sự kiện này, nên chiều nay tôi sẽ gửi lịch mới."]],"qs":[{"n":86,"q":"What are the listeners asked to do?","qvi":"Người nghe được yêu cầu làm gì?","opts":["Wait at a checkout area","Promote an event","Set up a display","Unload items quickly"],"vi":["Đợi ở quầy thanh toán","Quảng bá sự kiện","Dựng kệ trưng bày","Dỡ hàng nhanh"],"ans":"B","xp":"'Be sure to tell shoppers about it and encourage them to attend' → quảng bá sự kiện → (B). (C) kệ đã được dựng rồi."},{"n":87,"q":"What does the speaker suggest when he says, \"we haven't done anything\"?","qvi":"Người nói ngụ ý gì khi nói \"chúng ta không thay đổi gì\"?","opts":["The listeners are working less efficiently than expected.","The listeners should not feel responsible for an error.","The listeners do not need to worry about a regulation.","The listeners can find items in their usual place."],"vi":["Người nghe làm việc kém hiệu quả.","Người nghe không phải chịu trách nhiệm về lỗi.","Người nghe không cần lo về quy định.","Người nghe tìm thấy hàng ở chỗ cũ."],"ans":"D","xp":"'As for her other novels, we haven't done anything, so you know where they are' → các sách khác vẫn ở chỗ cũ → (D)."},{"n":88,"q":"What does the speaker mention about the schedule issued on June 3?","qvi":"Người nói nói gì về lịch làm việc phát ngày 3 tháng 6?","opts":["It was distributed late.","It uses a new policy.","It has been changed.","It is posted in the break room."],"vi":["Được phát muộn.","Áp dụng chính sách mới.","Đã được thay đổi.","Được dán ở phòng nghỉ."],"ans":"C","xp":"'Please ignore the work schedule that I e-mailed on June 3. I've made some adjustments' → (C)."}],"a":"XC-T09-86-88.mp3"},{"ns":[89,91],"script":[["","It's five o'clock, time for the community news report. City officials have announced plans for a cleanup day at Bonway Park this Saturday. Volunteers from around the community will assist with picking up litter, planting flowers, and painting playground equipment. Local hardware store Chester Hardware has generously contributed paint and brushes for the project. If you are interested in volunteering for this project, please call Robert Tindall at the city planner's office. Please note that water will be provided, but volunteers are encouraged to bring a packed lunch if they plan to stay all day. To see before and after photographs of the park, check out the city's Web site after the weekend.","Đã 5 giờ, đến giờ bản tin cộng đồng. Chính quyền thành phố đã công bố kế hoạch ngày dọn dẹp công viên Bonway vào thứ Bảy này. Tình nguyện viên trong cộng đồng sẽ cùng nhặt rác, trồng hoa và sơn lại đồ chơi ở sân chơi. Cửa hàng ngũ kim địa phương Chester Hardware đã hào phóng tặng sơn và cọ cho dự án. Nếu bạn muốn làm tình nguyện viên, hãy gọi ông Robert Tindall ở văn phòng quy hoạch thành phố. Xin lưu ý sẽ có nước uống, nhưng tình nguyện viên nên mang theo cơm trưa nếu định ở cả ngày. Để xem ảnh công viên trước và sau khi dọn, hãy vào trang web của thành phố sau cuối tuần."]],"qs":[{"n":89,"q":"What is the main topic of the report?","qvi":"Chủ đề chính của bản tin là gì?","opts":["A political debate","A community festival","A cleanup project","A business acquisition"],"vi":["Tranh luận chính trị","Lễ hội cộng đồng","Dự án dọn dẹp","Thâu tóm doanh nghiệp"],"ans":"C","xp":"'plans for a cleanup day at Bonway Park' → (C)."},{"n":90,"q":"According to the speaker, what has a local business done?","qvi":"Theo người nói, một doanh nghiệp địa phương đã làm gì?","opts":["Donated some supplies","Offered to train workers","Posted informational signs","Planned a meal"],"vi":["Tặng vật dụng","Đề nghị đào tạo","Dựng biển thông tin","Lên kế hoạch bữa ăn"],"ans":"A","xp":"'Chester Hardware has generously contributed paint and brushes' → contributed = donated → (A)."},{"n":91,"q":"According to the speaker, what can listeners do on the Web site?","qvi":"Theo người nói, người nghe có thể làm gì trên trang web?","opts":["Enter a prize drawing","Sign up for an activity","Download an event schedule","View some pictures"],"vi":["Tham gia bốc thăm trúng thưởng","Đăng ký hoạt động","Tải lịch sự kiện","Xem ảnh"],"ans":"D","xp":"'To see before and after photographs of the park, check out the city's Web site' → (D). (B) đăng ký bằng cách gọi điện."}],"a":"XC-T09-89-91.mp3"},{"ns":[92,94],"script":[["","Hi, Mr. Ferguson. It's Tiffany Baldwin from Alston Renewables. I got your message saying that you are interested in having solar panels installed on the rooftop of your office building. By using our products, you can greatly reduce your monthly electricity bills. We installed a system at Shoal Tech a few months ago, and they cut their bills by eighty percent without making any other changes. As you can see, the system easily pays for itself over time. I would be happy to visit your business next week to discuss the options further. I'll be out of town on business on Tuesday, but any other day is okay. Please call me back at 555-7799.","Chào ông Ferguson. Tôi là Tiffany Baldwin ở Alston Renewables. Tôi đã nhận tin nhắn ông muốn lắp tấm pin mặt trời trên mái tòa văn phòng. Dùng sản phẩm của chúng tôi, ông có thể giảm mạnh tiền điện hằng tháng. Vài tháng trước chúng tôi lắp hệ thống cho Shoal Tech, và họ giảm được 80% tiền điện mà không phải thay đổi gì khác. Như ông thấy, hệ thống dễ dàng tự hoàn vốn theo thời gian. Tôi rất sẵn lòng đến công ty ông tuần sau để bàn thêm. Thứ Ba tôi đi công tác, nhưng ngày nào khác cũng được. Vui lòng gọi lại cho tôi theo số 555-7799."]],"qs":[{"n":92,"q":"What does the speaker's business most likely specialize in?","qvi":"Công ty của người nói nhiều khả năng chuyên về lĩnh vực gì?","opts":["Trade relations","Renewable energy","Chemical manufacturing","Computer technology"],"vi":["Quan hệ thương mại","Năng lượng tái tạo","Sản xuất hóa chất","Công nghệ máy tính"],"ans":"B","xp":"'Alston Renewables... solar panels' → năng lượng tái tạo → (B)."},{"n":93,"q":"Why does the speaker say, \"they cut their bills by eighty percent\"?","qvi":"Vì sao người nói nói \"họ giảm được 80% tiền điện\"?","opts":["To support a claim","To praise a competitor","To explain a fee","To correct an error"],"vi":["Để chứng minh cho một nhận định","Để khen đối thủ","Để giải thích một khoản phí","Để sửa lỗi"],"ans":"A","xp":"Cô vừa nói 'you can greatly reduce your monthly electricity bills', rồi đưa ví dụ Shoal Tech giảm 80% → dẫn chứng cho lời mình nói → (A)."},{"n":94,"q":"What does the speaker plan to do on Tuesday?","qvi":"Thứ Ba người nói định làm gì?","opts":["Visit the listener's office","Sign a contract","Take a business trip","Attend a conference"],"vi":["Đến văn phòng người nghe","Ký hợp đồng","Đi công tác","Dự hội nghị"],"ans":"C","xp":"'I'll be out of town on business on Tuesday' → (C)."}],"a":"XC-T09-92-94.mp3"},{"ns":[95,97],"script":[["","You're listening to Home Solutions, the show that brings tips to all of those moms and dads out there trying to keep things running smoothly. And speaking of smooth, we've got some tasty smoothie recipes for you today. They're easy to make, and you can get your kids to eat more fruit. Now, the thing I love about smoothies is that you can just use what you have on hand. For example, the other day, I didn't have any almond milk, so I used cream and ice cubes instead. It was delicious! We'd like to hear what you think of these recipes and our show, so please leave a comment on our Web site.","Bạn đang nghe Home Solutions, chương trình mang mẹo vặt đến các ông bố bà mẹ đang cố giữ mọi việc trôi chảy. Nói đến trôi chảy, hôm nay chúng tôi có vài công thức sinh tố ngon cho bạn. Chúng dễ làm và giúp con bạn ăn nhiều trái cây hơn. Điều tôi thích ở sinh tố là có gì dùng nấy. Ví dụ, hôm trước tôi không có sữa hạnh nhân nên dùng kem và đá viên thay vào. Ngon lắm! Chúng tôi muốn biết bạn nghĩ gì về các công thức và chương trình, nên hãy để lại bình luận trên trang web nhé."]],"qs":[{"n":95,"q":"Who is the broadcast intended for?","qvi":"Chương trình dành cho ai?","opts":["Parents","Nutritionists","Fitness instructors","Professional chefs"],"vi":["Cha mẹ","Chuyên gia dinh dưỡng","Huấn luyện viên thể hình","Đầu bếp chuyên nghiệp"],"ans":"A","xp":"'the show that brings tips to all of those moms and dads' → (A)."},{"n":96,"q":"Look at the graphic. Which recipe has the speaker tried adjusting?","qvi":"Nhìn hình. Người nói đã thử thay đổi công thức nào?","opts":["Pineapple","Grape","Mango","Strawberry"],"vi":["Dứa","Nho","Xoài","Dâu tây"],"ans":"D","xp":"'I didn't have any almond milk, so I used cream and ice cubes instead'; bảng: Strawberry = Strawberries + Almond Milk → (D)."},{"n":97,"q":"What are the listeners encouraged to do?","qvi":"Người nghe được khuyến khích làm gì?","opts":["Upload some images","Add comments online","Try a kitchen appliance","Create their own recipes"],"vi":["Tải ảnh lên","Bình luận trên mạng","Dùng thử đồ bếp","Tự sáng tạo công thức"],"ans":"B","xp":"'please leave a comment on our Web site' → (B)."}],"a":"XC-T09-95-97.mp3","img":"g95.png"},{"ns":[98,100],"script":[["","It's a pleasure to welcome you all to the annual conference of video game developers. I hope you enjoy meeting others in your field. Lunch will be served in room 103 at 12:30 P.M., so don't forget to tell the staff at the registration desk whether you want the vegetarian roll or the ham sandwich. Also, please note that there has been a change in the schedule. The speaker for the eleven o'clock time slot missed his flight. Therefore, Keith Baxter will be filling in with a different presentation at eleven o'clock. Before we begin, Daniel Holland, who oversees all of this building's operations, will give you a quick safety briefing about fire evacuation procedures.","Rất vui được chào đón mọi người đến hội nghị thường niên của các nhà phát triển trò chơi điện tử. Mong mọi người vui khi gặp gỡ đồng nghiệp trong ngành. Bữa trưa sẽ phục vụ ở phòng 103 lúc 12 giờ 30, nên đừng quên báo nhân viên ở quầy đăng ký bạn muốn bánh cuộn chay hay bánh mì kẹp giăm bông. Ngoài ra, xin lưu ý lịch trình có thay đổi. Diễn giả khung 11 giờ bị lỡ chuyến bay. Vì vậy Keith Baxter sẽ thay thế bằng một bài trình bày khác lúc 11 giờ. Trước khi bắt đầu, ông Daniel Holland, người phụ trách mọi hoạt động của tòa nhà này, sẽ hướng dẫn nhanh về an toàn và quy trình sơ tán khi có cháy."]],"qs":[{"n":98,"q":"What are the listeners reminded to do?","qvi":"Người nghe được nhắc làm gì?","opts":["Turn off their cell phones","Wear their visitor badges","Indicate a meal preference","Retrieve their belongings"],"vi":["Tắt điện thoại","Đeo thẻ khách","Cho biết lựa chọn món ăn","Lấy lại đồ đạc"],"ans":"C","xp":"'don't forget to tell the staff... whether you want the vegetarian roll or the ham sandwich' → (C)."},{"n":99,"q":"Look at the graphic. Which talk has been replaced?","qvi":"Nhìn hình. Bài nói nào đã bị thay?","opts":["Bad Design and How to Fix It","Making Cooperative Games","Advancements in Virtual Reality","Marketing Your First Game"],"vi":["Bad Design and How to Fix It","Making Cooperative Games","Advancements in Virtual Reality","Marketing Your First Game"],"ans":"C","xp":"'The speaker for the eleven o'clock time slot missed his flight'; bảng: 11:00 A.M. – \"Advancements in Virtual Reality\" → (C)."},{"n":100,"q":"Who is Daniel Holland?","qvi":"Daniel Holland là ai?","opts":["An event planner","A building manager","A conference presenter","An award nominee"],"vi":["Người tổ chức sự kiện","Quản lý tòa nhà","Diễn giả hội nghị","Người được đề cử giải"],"ans":"B","xp":"'Daniel Holland, who oversees all of this building's operations' → quản lý tòa nhà → (B)."}],"a":"XC-T09-98-100.mp3","img":"g98.png"}]},"rc":{"p5":[{"n":101,"q":"Traffic was rerouted while the work crew painted new lane lines ------- the downtown streets.","opts":["than","until","on","as"],"ans":"C","xp":"Giới từ. Kẻ vạch làn đường 'trên' các con phố → (C) on. (A) than dùng trong so sánh, (B) until chỉ thời gian, (D) as 'như là' không hợp.\nDịch: Giao thông được phân luồng trong lúc đội thi công kẻ vạch làn đường mới trên các tuyến phố trung tâm."},{"n":102,"q":"Customers interested in top-quality kitchen appliances should read ------- brochure.","opts":["ours","our","theirs","they"],"ans":"B","xp":"Đại từ. Trước danh từ 'brochure' cần tính từ sở hữu → (B) our. (A)(C) đại từ sở hữu không đứng trước danh từ, (D) they là chủ ngữ.\nDịch: Khách hàng quan tâm đến đồ gia dụng nhà bếp cao cấp nên đọc tờ giới thiệu của chúng tôi."},{"n":103,"q":"Among the articles included in this month's journal, most readers agree that Dr. Cavalcanti's piece was the most -------.","opts":["prompt","dissatisfied","informative","constant"],"ans":"C","xp":"Từ vựng. Bài viết 'nhiều thông tin nhất' → (C) informative. (A) prompt 'nhanh chóng', (B) dissatisfied 'không hài lòng' (dùng cho người), (D) constant 'liên tục'.\nDịch: Trong các bài báo của tạp chí tháng này, hầu hết độc giả đồng ý rằng bài của tiến sĩ Cavalcanti có nhiều thông tin nhất."},{"n":104,"q":"The bank teller assured Ms. Reeves that the ------- of the document would be protected.","opts":["confident","confidentially","confidential","confidentiality"],"ans":"D","xp":"Từ loại. Sau 'the' và trước 'of' cần danh từ → (D) confidentiality 'tính bảo mật'. (A)(C) tính từ, (B) trạng từ.\nDịch: Giao dịch viên ngân hàng cam đoan với bà Reeves rằng tính bảo mật của tài liệu sẽ được bảo vệ."},{"n":105,"q":"The impressive ------- of the Winchell Dance Group has resulted in rave reviews by critics.","opts":["disposal","performance","renovation","compensation"],"ans":"B","xp":"Từ vựng. Buổi biểu diễn ấn tượng của đoàn múa nhận nhiều lời khen → (B) performance. (A) disposal 'việc xử lý', (C) renovation 'cải tạo', (D) compensation 'bồi thường'.\nDịch: Màn trình diễn ấn tượng của đoàn múa Winchell đã nhận được nhiều lời khen từ giới phê bình."},{"n":106,"q":"Employees who have recently ------- a professional seminar are asked to give feedback.","opts":["to attend","attending","attended","attend"],"ans":"C","xp":"Thì động từ. Sau 'have recently' cần V3 (hiện tại hoàn thành) → (C) attended. (A)(B)(D) không đi sau 'have'.\nDịch: Những nhân viên vừa dự hội thảo chuyên môn được đề nghị gửi phản hồi."},{"n":107,"q":"The water filter's ------- design reduces the growth of mold and bacteria on the surface.","opts":["innovatively","innovating","innovative","innovations"],"ans":"C","xp":"Từ loại. Giữa sở hữu cách 'The water filter's' và danh từ 'design' cần tính từ → (C) innovative 'sáng tạo'. (A) trạng từ, (B) V-ing, (D) danh từ số nhiều.\nDịch: Thiết kế sáng tạo của bộ lọc nước giúp giảm nấm mốc và vi khuẩn phát triển trên bề mặt."},{"n":108,"q":"The new Yao Auto commercial targets young professionals ------- than the campaign from last year.","opts":["specifically","specificity","specific","more specifically"],"ans":"D","xp":"So sánh. Có 'than' phía sau → so sánh hơn (D) more specifically 'cụ thể hơn' (trạng từ bổ nghĩa cho 'targets'). (A) trạng từ dạng thường, (B) danh từ, (C) tính từ.\nDịch: Quảng cáo mới của Yao Auto nhắm cụ thể vào giới trẻ đi làm hơn chiến dịch năm ngoái."},{"n":109,"q":"Please be sure to ------- the registration form to the event planners no later than Friday.","opts":["obtain","accept","submit","praise"],"ans":"C","xp":"Từ vựng. submit the registration form = nộp phiếu đăng ký → (C). (A) obtain 'lấy được', (B) accept 'chấp nhận', (D) praise 'khen' không hợp với 'to the event planners'.\nDịch: Vui lòng nộp phiếu đăng ký cho ban tổ chức sự kiện chậm nhất vào thứ Sáu."},{"n":110,"q":"The committee will discuss each new product presented and select ------- that has the best chance of market success.","opts":["other","some","one","both"],"ans":"C","xp":"Đại từ. 'chọn một sản phẩm có cơ hội thành công nhất' + động từ số ít 'has' → (C) one. (B) some, (D) both đi với động từ số nhiều; (A) other cần danh từ theo sau.\nDịch: Ủy ban sẽ thảo luận từng sản phẩm mới được giới thiệu và chọn ra một sản phẩm có cơ hội thành công nhất trên thị trường."},{"n":111,"q":"The sales manager requested ------- to a few of the slides in the presentation.","opts":["transfers","documents","standards","revisions"],"ans":"D","xp":"Từ vựng. request revisions to = yêu cầu sửa đổi → (D). (A) transfers 'chuyển', (B) documents 'tài liệu', (C) standards 'tiêu chuẩn' không hợp với 'to a few of the slides'.\nDịch: Trưởng phòng kinh doanh yêu cầu sửa vài trang trình chiếu trong bài thuyết trình."},{"n":112,"q":"------- weeks of intense negotiations, the merger between GW Sports and Poncia Inc. was finally agreed.","opts":["After","Between","Before","Even"],"ans":"A","xp":"Giới từ. 'Sau nhiều tuần đàm phán căng thẳng, việc sáp nhập cuối cùng được chốt' → (A) After. (B) Between cần hai đối tượng, (C) Before trái nghĩa với 'finally', (D) Even không phải giới từ.\nDịch: Sau nhiều tuần đàm phán căng thẳng, việc sáp nhập giữa GW Sports và Poncia Inc. cuối cùng đã được thống nhất."},{"n":113,"q":"------- considering the opinions of employees is important, leaders must be capable of following their own instincts.","opts":["Meanwhile","Rather","Although","Regardless"],"ans":"C","xp":"Liên từ. Hai mệnh đề đối lập: 'xem xét ý kiến nhân viên là quan trọng' – 'lãnh đạo phải biết làm theo trực giác của mình' → (C) Although 'mặc dù'. (A) Meanwhile, (B) Rather là trạng từ, (D) Regardless (of) không nối mệnh đề.\nDịch: Mặc dù xem xét ý kiến nhân viên là quan trọng, người lãnh đạo phải có khả năng làm theo trực giác của mình."},{"n":114,"q":"Park visitors should be aware ------- the trails can become very slippery in rainy weather.","opts":["so","that","while","of"],"ans":"B","xp":"Liên từ. be aware that + mệnh đề = biết rằng → (B). (D) be aware of + danh từ (không + mệnh đề), (A) so, (C) while không hợp.\nDịch: Khách tham quan công viên nên biết rằng đường mòn có thể rất trơn khi trời mưa."},{"n":115,"q":"City officials in Nashville plan to make an infrastructure ------- as soon as the funds are released.","opts":["investing","investment","invest","investors"],"ans":"B","xp":"Từ loại. Sau danh từ 'infrastructure' cần danh từ tạo danh từ ghép; make an investment = đầu tư → (B). (D) investors là người, số nhiều không đi với 'an'; (A) V-ing, (C) động từ.\nDịch: Chính quyền thành phố Nashville dự định đầu tư vào cơ sở hạ tầng ngay khi có ngân sách."},{"n":116,"q":"Maxwell Cleaning Supplies ------- that its dishwashing liquid dissolves grease better than any other brand.","opts":["modifies","claims","attempts","involves"],"ans":"B","xp":"Từ vựng. claim that = tuyên bố rằng → (B). (A) modifies 'sửa đổi', (C) attempts 'cố gắng' (+ to V), (D) involves 'liên quan' không đi với 'that'.\nDịch: Maxwell Cleaning Supplies tuyên bố nước rửa chén của họ tẩy dầu mỡ tốt hơn mọi nhãn hiệu khác."},{"n":117,"q":"The Lansberry Business Institute offers a broad ------- of courses for professionals in a number of fields.","opts":["method","range","parcel","surplus"],"ans":"B","xp":"Từ vựng. a broad range of = nhiều, đa dạng → (B). (A) method 'phương pháp', (C) parcel 'bưu kiện', (D) surplus 'thặng dư'.\nDịch: Viện Kinh doanh Lansberry có nhiều khóa học cho người đi làm ở nhiều lĩnh vực."},{"n":118,"q":"Art collectors should highly ------- the talent demonstrated in painter Ella Padovesi's new exhibition.","opts":["valued","value","valuing","valuable"],"ans":"B","xp":"Động từ. Sau động từ khiếm khuyết 'should' (+ trạng từ 'highly') cần động từ nguyên thể → (B) value 'đánh giá cao'. (A) V3, (C) V-ing, (D) tính từ.\nDịch: Giới sưu tầm nghệ thuật hẳn sẽ đánh giá cao tài năng thể hiện trong triển lãm mới của họa sĩ Ella Padovesi."},{"n":119,"q":"Those who are familiar with the brand will notice designer Paula Mazzi's clothing -------, including in rural areas.","opts":["otherwise","moreover","everywhere","mutually"],"ans":"C","xp":"Trạng từ. 'sẽ thấy quần áo của Paula Mazzi ở khắp nơi, kể cả nông thôn' → (C) everywhere. (A) otherwise 'nếu không thì', (B) moreover 'hơn nữa', (D) mutually 'lẫn nhau'.\nDịch: Những ai quen thuộc thương hiệu sẽ thấy quần áo của nhà thiết kế Paula Mazzi ở khắp nơi, kể cả vùng nông thôn."},{"n":120,"q":"Holding the community parade in the coldest month of the year would not be ------- for planners.","opts":["senses","sensing","sensible","sense"],"ans":"C","xp":"Từ loại. Sau 'would not be' cần tính từ → (C) sensible 'hợp lý'. (A)(D) danh từ/động từ, (B) V-ing.\nDịch: Tổ chức diễu hành cộng đồng vào tháng lạnh nhất năm là không hợp lý với ban tổ chức."},{"n":121,"q":"If your package does not include all of the ------- items on your invoice, please contact customer service.","opts":["listed","reassured","dominated","addressed"],"ans":"A","xp":"Từ vựng. the items listed on your invoice = các món được liệt kê trên hóa đơn → (A). (B) reassured 'được trấn an', (C) dominated 'bị chi phối', (D) addressed 'được gửi đến/giải quyết'.\nDịch: Nếu kiện hàng không có đủ các món được liệt kê trên hóa đơn, vui lòng liên hệ bộ phận chăm sóc khách hàng."},{"n":122,"q":"The winner of the election will be officially announced ------- all of the ballots have been counted.","opts":["ever","from","these","once"],"ans":"D","xp":"Liên từ. Sau chỗ trống là mệnh đề 'all of the ballots have been counted' → (D) once 'một khi, ngay khi'. (A) ever, (C) these không nối mệnh đề, (B) from là giới từ.\nDịch: Người thắng cử sẽ được công bố chính thức sau khi kiểm xong tất cả các phiếu."},{"n":123,"q":"The hiring committee's selection meeting was short, as the members ------- voted to offer the job to Ms. Steele.","opts":["nearly","unanimously","intensively","frequently"],"ans":"B","xp":"Từ vựng. Buổi họp ngắn vì các thành viên 'nhất trí' bỏ phiếu → (B) unanimously. (A) nearly 'gần như', (C) intensively 'mạnh mẽ', (D) frequently 'thường xuyên' không giải thích được vì sao họp ngắn.\nDịch: Buổi họp chọn người của hội đồng tuyển dụng diễn ra ngắn vì các thành viên nhất trí mời bà Steele nhận việc."},{"n":124,"q":"Businesses usually need to get government ------- in order to import goods for commercial use.","opts":["permit","permission","permitted","permitting"],"ans":"B","xp":"Từ loại. Sau danh từ 'government' làm tân ngữ của 'get' cần danh từ không đếm được → (B) permission 'sự cho phép'. (A) permit là danh từ đếm được cần 'a', (C)(D) V3/V-ing.\nDịch: Doanh nghiệp thường cần sự cho phép của chính phủ để nhập khẩu hàng hóa vì mục đích thương mại."},{"n":125,"q":"Nametags were distributed to the workshop participants ------- everyone could get to know each other more easily.","opts":["as if","except","so that","whether"],"ans":"C","xp":"Liên từ chỉ mục đích. 'Phát thẻ tên để mọi người dễ làm quen' → (C) so that. (A) as if 'như thể', (B) except 'ngoại trừ', (D) whether 'liệu'.\nDịch: Thẻ tên được phát cho người tham dự hội thảo để mọi người dễ làm quen với nhau hơn."},{"n":126,"q":"When fully -------, the departmental reports showed a trend toward high employee satisfaction.","opts":["compile","compiles","compiled","compiler"],"ans":"C","xp":"Mệnh đề rút gọn. 'When fully compiled' = When (the reports were) fully compiled — báo cáo 'được tổng hợp' → bị động V3 (C). (A)(B) động từ chủ động, (D) danh từ chỉ người/máy.\nDịch: Khi được tổng hợp đầy đủ, các báo cáo của phòng ban cho thấy xu hướng nhân viên rất hài lòng."},{"n":127,"q":"If either party wants to make contract adjustments ------- those agreed upon in this session, another meeting is needed.","opts":["into","during","beyond","until"],"ans":"C","xp":"Giới từ. beyond + N = vượt quá, ngoài → 'điều chỉnh ngoài những gì đã thống nhất' (C). (A) into, (B) during, (D) until không hợp.\nDịch: Nếu một bên muốn điều chỉnh hợp đồng ngoài những điều đã thống nhất trong buổi này, cần có một cuộc họp khác."},{"n":128,"q":"On the day that Shine Dental Clinic moved into the third-floor suite, the landlord added its name to the directory -------.","opts":["downstairs","until now","throughout","all in all"],"ans":"A","xp":"Trạng từ. Phòng khám ở tầng 3, chủ nhà thêm tên vào bảng chỉ dẫn 'ở tầng dưới' → (A) downstairs. (B) until now 'cho đến nay', (C) throughout 'khắp', (D) all in all 'nhìn chung'.\nDịch: Hôm phòng khám nha khoa Shine chuyển vào tầng 3, chủ nhà đã thêm tên phòng khám vào bảng chỉ dẫn ở tầng dưới."},{"n":129,"q":"At the start of the press conference, a company spokesperson ------- reporters on the details of the merger.","opts":["briefed","recounted","discussed","expressed"],"ans":"A","xp":"Từ vựng. brief someone on something = báo cáo vắn tắt cho ai về việc gì → (A) briefed. (B) recounted 'kể lại', (C) discussed 'thảo luận', (D) expressed 'bày tỏ' không có cấu trúc 'người + on'.\nDịch: Đầu buổi họp báo, người phát ngôn công ty đã thông báo vắn tắt cho phóng viên về chi tiết vụ sáp nhập."},{"n":130,"q":"BT Kitchens makes the most efficient use of your space by creating completely ------- cabinets.","opts":["customizes","customized","customization","customize"],"ans":"B","xp":"Từ loại. Sau trạng từ 'completely' và trước danh từ 'cabinets' cần tính từ → (B) customized 'được làm theo yêu cầu'. (A)(D) động từ, (C) danh từ.\nDịch: BT Kitchens tận dụng tối đa không gian của bạn bằng cách làm tủ hoàn toàn theo yêu cầu."}],"p6":[{"ns":[131,134],"head":"Questions 131-134 refer to the following e-mail.","passage":"<div class=\"hdr\"><p><b>To:</b> Ravi Harish &lt;harishravi@dolainteriors.com&gt;</p><p><b>From:</b> Angelina Kohl &lt;angelina@homedecmag.com&gt;</p><p><b>Date:</b> October 3</p><p><b>Subject:</b> Home Decorating Magazine Article</p></div><p>Dear Mr. Harish,</p><p>Congratulations! Dola Interiors has been chosen as a \"Style Star\" for this quarter. Our magazine will be <span class=\"blank\" data-n=\"131\">-------</span> your firm in the November issue. The \"Style Star\" section of our magazine highlights the work of <span class=\"blank\" data-n=\"132\">-------</span> that are setting trends for interior design.</p><p>Do you have time for a phone interview with one of our staff members? <span class=\"blank\" data-n=\"133\">-------</span> They should outline your corporate mission as well as your design strategy. This will bring some authenticity to the article. We would need to be in touch with you <span class=\"blank\" data-n=\"134\">-------</span> October 25 in order to meet our publication deadline.</p><p>Sincerely,<br>Angelina Kohl<br>Assistant Editor, Home Decorating Magazine</p>","vi":"Người nhận: Ravi Harish | Người gửi: Angelina Kohl | Ngày: 3/10 | Chủ đề: Bài viết trên tạp chí Home Decorating\n\nKính gửi ông Harish,\n\nXin chúc mừng! Dola Interiors đã được chọn là \"Ngôi sao Phong cách\" của quý này. Tạp chí chúng tôi sẽ giới thiệu công ty ông trong số tháng 11. Mục \"Ngôi sao Phong cách\" giới thiệu tác phẩm của các doanh nghiệp đang dẫn dắt xu hướng thiết kế nội thất.\n\nÔng có thời gian phỏng vấn qua điện thoại với một nhân viên của chúng tôi không? Vài câu trích dẫn của ông sẽ rất hữu ích. Những câu này nên nêu sứ mệnh công ty cũng như chiến lược thiết kế của ông. Điều này sẽ làm bài viết chân thực hơn. Chúng tôi cần liên lạc với ông trước ngày 25/10 để kịp hạn xuất bản.\n\nTrân trọng,\nAngelina Kohl – Trợ lý biên tập, tạp chí Home Decorating","qs":[{"n":131,"opts":["featuring","featured","features","feature"],"ans":"A","xp":"Thì động từ. 'will be + V-ing' (tương lai tiếp diễn) → (A) featuring 'giới thiệu'. (B) will be featured là bị động, nhưng phía sau có tân ngữ 'your firm' nên phải chủ động. (C)(D) không đi sau 'will be'."},{"n":132,"opts":["procedures","enterprises","materials","patterns"],"ans":"B","xp":"Từ vựng. 'the work of enterprises that are setting trends' = tác phẩm của các doanh nghiệp đang dẫn dắt xu hướng (Dola Interiors là một công ty) → (B). (A) procedures 'quy trình', (C) materials 'vật liệu', (D) patterns 'hoa văn' không tạo ra 'work' và 'set trends'."},{"n":133,"opts":["The committee will select the questions.","Our magazine's readership has been growing.","A few quotes from you would be helpful.","We loved the photos of the decorated room."],"ans":"C","xp":"Điền câu. Câu sau: 'They should outline your corporate mission...' – 'They' phải là thứ do ông nói ra → 'Vài câu trích dẫn của ông sẽ hữu ích' (C); 'They' = quotes."},{"n":134,"opts":["besides","of","by","within"],"ans":"C","xp":"Giới từ. by + mốc thời gian = trước, chậm nhất là → 'by October 25' (C). (D) within + khoảng thời gian, (A) besides 'ngoài ra', (B) of không hợp."}]},{"ns":[135,138],"head":"Questions 135-138 refer to the following e-mail.","passage":"<div class=\"hdr\"><p><b>To:</b> Livia Castro</p><p><b>From:</b> Souza Electronics</p><p><b>Date:</b> August 3</p><p><b>Subject:</b> Order #52490</p></div><p>Dear Ms. Castro,</p><p>Your order has been successfully placed through our online system. Upon <span class=\"blank\" data-n=\"135\">-------</span> of the packaging process, we will e-mail you again to inform you that the items have been dispatched. <span class=\"blank\" data-n=\"136\">-------</span> You may use it to check the status of your delivery.</p><p>As soon as you receive your order, we <span class=\"blank\" data-n=\"137\">-------</span> you to verify the contents of the package. If there is an issue, we are <span class=\"blank\" data-n=\"138\">-------</span> to solve it more easily on the delivery day.</p><p>Sincerely,<br>Souza Electronics</p>","vi":"Người nhận: Livia Castro | Người gửi: Souza Electronics | Ngày: 3/8 | Chủ đề: Đơn hàng #52490\n\nKính gửi chị Castro,\n\nĐơn hàng của chị đã được đặt thành công qua hệ thống trực tuyến. Khi hoàn tất khâu đóng gói, chúng tôi sẽ e-mail lần nữa để báo hàng đã được gửi đi. Sau đó chị sẽ nhận được mã theo dõi đơn hàng. Chị có thể dùng mã này để kiểm tra tình trạng giao hàng.\n\nNgay khi nhận hàng, chúng tôi khuyến khích chị kiểm tra đồ trong kiện hàng. Nếu có vấn đề, chúng tôi có thể giải quyết dễ dàng hơn ngay trong ngày giao hàng.\n\nTrân trọng,\nSouza Electronics","qs":[{"n":135,"opts":["elimination","completion","intersection","generation"],"ans":"B","xp":"Từ vựng. upon completion of = khi hoàn tất → 'Upon completion of the packaging process' (B). (A) elimination 'loại bỏ', (C) intersection 'giao lộ', (D) generation 'thế hệ/tạo ra'."},{"n":136,"opts":["The component is currently out of stock.","Your account will be credited the difference.","We can assist you with assembly.","You will then receive a tracking code."],"ans":"D","xp":"Điền câu. Câu sau: 'You may use it to check the status of your delivery' → 'it' là mã theo dõi → (D) 'Sau đó chị sẽ nhận được mã theo dõi'."},{"n":137,"opts":["have encouraged","were encouraging","encouraged","encourage"],"ans":"D","xp":"Thì động từ. Lời khuyên chung hiện tại cho việc sắp tới → hiện tại đơn (D) encourage; encourage + O + to V. (A)(B)(C) là hoàn thành/quá khứ, không hợp."},{"n":138,"opts":["able","comprehensive","talented","acceptable"],"ans":"A","xp":"Từ vựng. be able to V = có thể → (A). (B) comprehensive 'toàn diện', (C) talented 'tài năng', (D) acceptable 'chấp nhận được' không đi với 'to solve'."}]},{"ns":[139,142],"head":"Questions 139-142 refer to the following information.","passage":"<p>Calls to international telephone numbers can be made from any office phone. First, dial 9 and then input the entire number when you hear the dial tone. As soon as your call <span class=\"blank\" data-n=\"139\">-------</span>, per-minute charges will start to accrue. As these charges can be expensive, the finance team may contact you to <span class=\"blank\" data-n=\"140\">-------</span> the reason for the call. There is no formal limit to the duration of international calls. <span class=\"blank\" data-n=\"141\">-------</span> If you are concerned about your amount of calling time within a given month, it is <span class=\"blank\" data-n=\"142\">-------</span> that you check with your supervisor. This will help you to ensure that you are keeping within a reasonable amount.</p>","vi":"Có thể gọi quốc tế từ bất kỳ điện thoại nào trong văn phòng. Trước tiên, bấm số 9 rồi nhập đầy đủ số điện thoại khi nghe tiếng tút. Ngay khi cuộc gọi được kết nối, phí tính theo phút bắt đầu cộng dồn. Vì phí này có thể cao, nhóm tài chính có thể liên hệ bạn để xác nhận lý do cuộc gọi. Không có giới hạn chính thức về thời lượng cuộc gọi quốc tế. Tuy nhiên, chúng tôi đề nghị hạn chế tối đa các cuộc gọi này. Nếu lo lắng về tổng thời gian gọi trong tháng, bạn nên hỏi ý kiến cấp trên. Điều này giúp bạn đảm bảo thời gian gọi ở mức hợp lý.","qs":[{"n":139,"opts":["connecting","connected","to connect","is connected"],"ans":"D","xp":"Thể bị động. Mệnh đề sau 'As soon as' cần động từ chính; cuộc gọi 'được kết nối' → bị động hiện tại (D) is connected. (A)(C) không phải động từ chính; (B) connected (chủ động quá khứ) cần tân ngữ và sai thì."},{"n":140,"opts":["adjust","relocate","confirm","terminate"],"ans":"C","xp":"Từ vựng. Phí cao nên nhóm tài chính có thể liên hệ để 'xác nhận lý do cuộc gọi' → (C) confirm. (A) adjust 'điều chỉnh', (B) relocate 'di dời', (D) terminate 'chấm dứt'."},{"n":141,"opts":["We do ask, however, that they are kept to a minimum.","Thank you for reviewing the budget carefully.","Your phone can be upgraded through the IT department.","Other staff members may be disturbed by the sound."],"ans":"A","xp":"Điền câu. Trước: 'Không có giới hạn chính thức về thời lượng'; sau: nói về lo ngại thời gian gọi → 'Tuy nhiên, chúng tôi đề nghị hạn chế tối đa' (A); 'however' tạo ý đối lập với câu trước."},{"n":142,"opts":["portable","significant","visible","advisable"],"ans":"D","xp":"Từ vựng. it is advisable that... = nên làm gì → (D). (A) portable 'di động', (B) significant 'quan trọng', (C) visible 'nhìn thấy được'."}]},{"ns":[143,146],"head":"Questions 143-146 refer to the following memo.","passage":"<div class=\"hdr\"><p><b>To:</b> All Staff</p><p><b>From:</b> Stella Reynell, Site Manager</p><p><b>Re:</b> Entertainment Coordinator</p><p><b>Date:</b> April 3</p></div><p>Dear Staff,</p><p>From next week, Laguna Botanical Gardens will advertise a job opening for a full-time entertainment coordinator. The <span class=\"blank\" data-n=\"143\">-------</span> of the \"Daisy Dance Show\" we held recently demonstrated the need for more activities on site, as they attract many more visitors than usual. The management team <span class=\"blank\" data-n=\"144\">-------</span> the first round of interviews for this position in the first week of May. <span class=\"blank\" data-n=\"145\">-------</span> Applications from the general public will also be considered, which is why we plan to post the opening on career Web sites. Those who are <span class=\"blank\" data-n=\"146\">-------</span> should pick up an application from the administrative office.</p><p>Sincerely,<br>Stella</p>","vi":"Gửi: Toàn thể nhân viên | Từ: Stella Reynell, Quản lý khu vườn | V/v: Điều phối viên giải trí | Ngày: 3/4\n\nGửi toàn thể nhân viên,\n\nTừ tuần sau, Vườn Bách thảo Laguna sẽ đăng tuyển một điều phối viên giải trí toàn thời gian. Sự thành công/được yêu thích của \"Daisy Dance Show\" vừa tổ chức cho thấy cần thêm hoạt động tại vườn, vì chúng thu hút nhiều khách hơn bình thường. Ban quản lý sẽ bắt đầu vòng phỏng vấn đầu tiên cho vị trí này vào tuần đầu tháng 5. Chúng tôi ưu tiên đề bạt một nhân viên hiện tại. Đơn ứng tuyển từ bên ngoài cũng sẽ được xem xét, vì vậy chúng tôi định đăng tin trên các trang web việc làm. Ai đủ điều kiện hãy đến văn phòng hành chính lấy đơn.\n\nTrân trọng,\nStella","qs":[{"n":143,"opts":["purpose","champion","popularity","courtesy"],"ans":"C","xp":"Từ vựng. Sự 'được yêu thích' của buổi diễn cho thấy cần thêm hoạt động vì chúng thu hút nhiều khách → (C) popularity. (A) purpose 'mục đích', (B) champion 'nhà vô địch', (D) courtesy 'phép lịch sự'."},{"n":144,"opts":["was beginning","began","has begun","will begin"],"ans":"D","xp":"Thì động từ. Thư viết ngày 3/4, tin tuyển dụng đăng từ tuần sau, phỏng vấn 'in the first week of May' → tương lai (D) will begin."},{"n":145,"opts":["Our preference is to promote a current employee.","The managers usually meet once a month.","We hope you will all enjoy the performance.","The peak season may be much busier than it was last year."],"ans":"A","xp":"Điền câu. Câu sau: 'Applications from the general public will ALSO be considered' (người ngoài CŨNG được xem xét) → câu trước nói về ứng viên nội bộ: 'Chúng tôi ưu tiên đề bạt nhân viên hiện tại' (A)."},{"n":146,"opts":["renegotiated","qualified","enrolled","affected"],"ans":"B","xp":"Từ vựng. Those who are qualified = những người đủ điều kiện → (B). (A) renegotiated 'được đàm phán lại', (C) enrolled 'đã ghi danh', (D) affected 'bị ảnh hưởng' không hợp."}]}],"p7":[{"ns":[147,148],"head":"Questions 147-148 refer to the following invitation.","passages":["<h3>Business Builders Luncheon</h3><p>Thursday, March 8<br>11:30 A.M. – 1:00 P.M.<br>Thai Garden, Private Meeting Room<br>1926 Lang Avenue<br>Bloomington, IL 61701</p><p><b>Speaker:</b> Georgia Rufin<br>\"Expanding Your Customer Base on a Budget\"</p><p>Tickets are $12 per person, which includes a three-course meal.<br>Please RSVP by March 1 so we may prepare the catering order.</p><p>Event Planner Tyson Lee: 555-7833</p>"],"vi":"Bữa trưa Business Builders\n\nThứ Năm, 8 tháng 3, 11:30 sáng – 1:00 chiều. Nhà hàng Thai Garden, phòng họp riêng, 1926 Lang Avenue, Bloomington.\nDiễn giả: Georgia Rufin – \"Mở rộng tập khách hàng với ngân sách hạn chế\"\nVé 12 đô mỗi người, gồm bữa ăn ba món.\nVui lòng xác nhận tham dự trước ngày 1/3 để chúng tôi chuẩn bị đặt món.\nNgười tổ chức: Tyson Lee, 555-7833","qs":[{"n":147,"q":"What will guests learn about at the event?","qvi":"Khách sẽ được học về điều gì tại sự kiện?","opts":["Creating a logo","Gaining more customers","Using budgeting software","Expanding their staff"],"ans":"B","xp":"Bài nói 'Expanding Your Customer Base on a Budget' = mở rộng tập khách hàng → có thêm khách hàng → (B). (C) lặp từ budget."},{"n":148,"q":"What is suggested about the event?","qvi":"Có thể suy ra điều gì về sự kiện?","opts":["Guests should indicate whether they plan to attend.","Groups can get a discount on the admission tickets.","The charge for the meal depends on what is ordered.","It is held every Thursday in March."],"ans":"A","xp":"'Please RSVP by March 1' (RSVP = xác nhận có tham dự hay không) → (A). (C) giá cố định 12 đô gồm bữa ăn."}]},{"ns":[149,150],"head":"Questions 149-150 refer to the following e-mail.","passages":["<div class=\"hdr\"><p><b>To:</b> Undisclosed Recipients</p><p><b>From:</b> &lt;service@romadaytours.it&gt;</p><p><b>Date:</b> May 19</p><p><b>Subject:</b> Rome is calling!</p></div><p>Tour Rome in style with Roma Day Tours' newest tour package: R360. We're offering it for a limited time for just €875, which includes entrance fees. This extravagant tour package takes you to Rome's best sites in a luxurious limousine, and group sizes are kept small so that you have extra attention from the tour guide. The R360 ticket can be used by up to ten people on one reservation.</p><p>Click here to start your journey!</p>"],"vi":"Người nhận: (ẩn danh) | Người gửi: service@romadaytours.it | Ngày: 19/5 | Chủ đề: Rome đang gọi bạn!\n\nHãy du lịch Rome thật sang trọng với gói tour mới nhất của Roma Day Tours: R360. Trong thời gian có hạn, giá chỉ 875 euro, đã gồm vé vào cửa. Gói tour xa hoa này đưa bạn đến những địa điểm đẹp nhất Rome bằng xe limousine sang trọng, và đoàn được giữ ở quy mô nhỏ để hướng dẫn viên chăm sóc bạn kỹ hơn. Vé R360 dùng được cho tối đa mười người trong một lần đặt.\n\nBấm vào đây để bắt đầu hành trình!","qs":[{"n":149,"q":"Why was the e-mail written?","qvi":"E-mail được viết nhằm mục đích gì?","opts":["To thank customers for their loyalty","To boost the sale of a luxury package","To recruit tour guides for the peak season","To publicize a schedule change"],"ans":"B","xp":"E-mail quảng cáo gói tour mới 'extravagant... luxurious limousine' với giá ưu đãi có hạn → thúc đẩy bán gói tour cao cấp → (B)."},{"n":150,"q":"What is indicated about the R360 ticket?","qvi":"Điều gì được cho biết về vé R360?","opts":["It is for groups of people booking together.","It is limited to adults only.","It includes all meals throughout the day.","It should be ordered by phone."],"ans":"A","xp":"'The R360 ticket can be used by up to ten people on one reservation' → dành cho nhóm đặt chung → (A). (C) chỉ gồm vé vào cửa, không nói bữa ăn."}]},{"ns":[151,152],"head":"Questions 151-152 refer to the following text message chain.","passages":["<div class=\"msg\"><p><b>Isabelle Chauncy (9:03 A.M.)</b></p><p>Hi, Beau. I'm in the storage area of the basement getting some items for the new employee. I saw that there's a spare computer monitor in here. Didn't you say you needed a second one for your desk?</p></div><div class=\"msg\"><p><b>Beau Esson (9:05 A.M.)</b></p><p>Yes, I did, but I wasn't approved for a new purchase. I didn't know that we had a spare. I'll have to test it to see whether it's working.</p></div><div class=\"msg\"><p><b>Isabelle Chauncy (9:06 A.M.)</b></p><p>Do you want me to bring it up to you with the other items?</p></div><div class=\"msg\"><p><b>Beau Esson (9:07 A.M.)</b></p><p>It's your call. If you have too much already, I can go and get it later. Thanks.</p></div>"],"vi":"Isabelle Chauncy (9:03): Chào Beau. Tôi đang ở kho dưới tầng hầm lấy đồ cho nhân viên mới. Tôi thấy ở đây có một màn hình máy tính dự phòng. Không phải anh nói cần thêm một cái cho bàn làm việc sao?\nBeau Esson (9:05): Đúng vậy, nhưng tôi không được duyệt mua mới. Tôi không biết là mình có màn hình dự phòng. Tôi sẽ phải thử xem nó còn chạy không.\nIsabelle Chauncy (9:06): Anh có muốn tôi mang nó lên cho anh cùng với các đồ khác không?\nBeau Esson (9:07): Tùy chị quyết. Nếu chị đã mang nhiều đồ quá thì để sau tôi tự xuống lấy. Cảm ơn chị.","qs":[{"n":151,"q":"Why did Ms. Chauncy contact Mr. Esson?","qvi":"Vì sao cô Chauncy liên hệ ông Esson?","opts":["To ask for assistance moving a desk","To suggest putting more items in storage","To check the arrival time of an employee","To find out if he wants some equipment"],"ans":"D","xp":"'there's a spare computer monitor in here. Didn't you say you needed a second one?' → hỏi ông có cần thiết bị không → (D)."},{"n":152,"q":"At 9:07 A.M., what does Mr. Esson mean when he writes, \"It's your call\"?","qvi":"Lúc 9:07, ông Esson có ý gì khi viết \"Tùy chị quyết\"?","opts":["Ms. Chauncy should make a decision about organizing an area.","Ms. Chauncy should decide whether to bring an item or not.","He will wait until an order is approved by the management.","He does not have time to fix Ms. Chauncy's computer."],"ans":"B","xp":"Cô hỏi có muốn cô mang màn hình lên không; ông đáp 'It's your call' (chị quyết định) và 'If you have too much already, I can go and get it later' → cô tự quyết có mang hay không → (B)."}]},{"ns":[153,154],"head":"Questions 153-154 refer to the following notice.","passages":["<h3>Aldridge Fabrics</h3><p>Managing Director: Michelle Struble<br>Production Manager: Allen Buchanan</p><p>We hope you enjoy your time at Aldridge Fabrics. For your safety, the safety of our staff, and the quality of our products, please follow the rules below throughout your tour. Additional gear is available from the production manager. Should you have any questions about carrying Aldridge Fabrics in your store, please speak to the managing director.</p><p><b>Do's</b></p><ul><li>Follow your guide's instructions at all times.</li><li>Keep your temporary ID badge visible.</li><li>Ask questions to workers not operating machinery.</li><li>Take photos (with the flash turned off).</li></ul><p><b>Don'ts</b></p><ul><li>Distract workers operating machinery.</li><li>Bring food or beverages into the production area.</li><li>Get separated from your group.</li></ul>"],"vi":"Aldridge Fabrics – Giám đốc điều hành: Michelle Struble – Quản lý sản xuất: Allen Buchanan\n\nChúc quý khách có thời gian vui vẻ tại Aldridge Fabrics. Vì sự an toàn của quý khách, của nhân viên và chất lượng sản phẩm, vui lòng tuân thủ các quy định dưới đây trong suốt chuyến tham quan. Có thể nhận thêm đồ bảo hộ từ quản lý sản xuất. Nếu có câu hỏi về việc bán vải Aldridge tại cửa hàng của quý khách, vui lòng hỏi giám đốc điều hành.\n\nNên: luôn làm theo hướng dẫn của hướng dẫn viên; đeo thẻ khách tạm thời ở chỗ dễ thấy; đặt câu hỏi cho công nhân không đang vận hành máy; chụp ảnh (tắt đèn flash).\nKhông nên: làm phân tâm công nhân đang vận hành máy; mang đồ ăn, thức uống vào khu sản xuất; tách khỏi đoàn.","qs":[{"n":153,"q":"Who most likely was the notice written for?","qvi":"Thông báo nhiều khả năng dành cho ai?","opts":["Fabric designers","Job recruiters","Plant visitors","Safety experts"],"ans":"C","xp":"'please follow the rules below throughout your tour'; 'Keep your temporary ID badge visible' → dành cho khách tham quan nhà máy → (C)."},{"n":154,"q":"According to the notice, what will Ms. Struble do?","qvi":"Theo thông báo, bà Struble sẽ làm gì?","opts":["Distribute some necessary gear","Provide product catalogs","Update the site's rules regularly","Handle inquiries regarding sales"],"ans":"D","xp":"Bà Struble là Managing Director; 'Should you have any questions about carrying Aldridge Fabrics in your store, please speak to the managing director' → trả lời câu hỏi về việc bán hàng → (D). (A) đồ bảo hộ do quản lý sản xuất phát."}]},{"ns":[155,157],"head":"Questions 155-157 refer to the following form.","passages":["<h3>Emerson Apartments Request Form</h3><p>Building Supervisor: Diego Landeros<br>d.landeros@emersonapt.com / 555-4848</p><table><tr><td>Tenant:</td><td>Elizabeth Swanson</td></tr><tr><td>Tower:</td><td>C</td></tr><tr><td>Unit:</td><td>516B</td></tr><tr><td>Contact Number:</td><td>555-4510</td></tr><tr><td>Type of Request:</td><td>Tenant's Unit [✓] / Common Areas – Indoor [ ] / Common Areas – Outdoor [ ]</td></tr></table><p><b>Description of Issue:</b> The valve for the gas fireplace is stuck closed, so it does not turn on. The property manager, Denise Platt, said it was not a safety issue (as there is no gas odor).</p><p><b>Notes:</b> Please let me know in advance when you plan to visit. I have two paintings hanging on the wall above the fireplace. I'll take these down shortly before the work begins to provide extra room for the technician.</p><p><b>FOR OFFICE USE ONLY</b><br>Date of Request: January 9 / Received by: Jerry Tobin<br>Ranking: Urgent [ ] Potentially Urgent [✓] High Priority [ ] Standard [ ]<br>Assigned to: Ryan Marrero<br>Instructions: Please call the tenant to inform her that you will visit today. The office can book a specialist if you determine from your inspection that it is necessary.</p>"],"vi":"Phiếu yêu cầu – Chung cư Emerson. Giám sát tòa nhà: Diego Landeros (d.landeros@emersonapt.com / 555-4848)\nNgười thuê: Elizabeth Swanson | Tòa: C | Căn hộ: 516B | Điện thoại: 555-4510 | Loại yêu cầu: căn hộ của người thuê [✓]\nMô tả sự cố: Van lò sưởi gas bị kẹt ở vị trí đóng nên không bật được. Quản lý tòa nhà, bà Denise Platt, nói đây không phải vấn đề an toàn (vì không có mùi gas).\nGhi chú: Vui lòng báo trước khi nào anh định đến. Tôi có hai bức tranh treo trên tường phía trên lò sưởi. Tôi sẽ gỡ chúng xuống ngay trước khi bắt đầu sửa để thợ có thêm chỗ làm việc.\nDÀNH CHO VĂN PHÒNG: Ngày yêu cầu: 9/1 | Người nhận: Jerry Tobin | Mức độ: Có thể khẩn cấp [✓] | Giao cho: Ryan Marrero\nHướng dẫn: Hãy gọi cho người thuê báo rằng anh sẽ đến hôm nay. Văn phòng có thể đặt thợ chuyên môn nếu qua kiểm tra anh thấy cần.","qs":[{"n":155,"q":"Why did Ms. Swanson submit the form?","qvi":"Vì sao bà Swanson nộp phiếu?","opts":["To tour a property","To update a billing method","To renew a lease","To schedule a repair"],"ans":"D","xp":"Phiếu báo 'The valve for the gas fireplace is stuck closed' và nhờ báo trước khi đến sửa → yêu cầu sửa chữa → (D)."},{"n":156,"q":"What does Ms. Swanson mention about some paintings?","qvi":"Bà Swanson nói gì về mấy bức tranh?","opts":["They will be removed from the wall.","They were received as a gift.","They have an unusual odor.","They were accidentally damaged."],"ans":"A","xp":"'I'll take these down shortly before the work begins' → tranh sẽ được gỡ khỏi tường → (A)."},{"n":157,"q":"Who will call Ms. Swanson on January 9?","qvi":"Ai sẽ gọi cho bà Swanson ngày 9/1?","opts":["Mr. Landeros","Ms. Platt","Mr. Tobin","Mr. Marrero"],"ans":"D","xp":"Ngày yêu cầu 9/1, 'Assigned to: Ryan Marrero'; hướng dẫn: 'Please call the tenant to inform her that you will visit today' → ông Marrero gọi → (D). (C) ông Tobin chỉ nhận phiếu."}]},{"ns":[158,160],"head":"Questions 158-160 refer to the following article.","passages":["<p>TAIPEI (October 7)—Sampaga, a Philippines-based home furnishings store, opened its first branch in Taiwan about three months ago. The brand is known for its affordable collections of home products with bright colors and joyful patterns. Sampaga is a household name across the Philippines. <span class=\"pos\">[1]</span></p><p>The new store is located in the popular Ximending neighborhood of Taipei. The store is not as large as most of the branches in the Philippines. <span class=\"pos\">[2]</span> However, its manager, Mei-hua Liu, has added her own idea—several small rooms set up like rooms in a house. They are decorated from top to bottom with Sampaga products. Ms. Liu believes this helps customers to visualize the products in their own homes.</p><p><span class=\"pos\">[3]</span> One top-selling product is the store's line of rugs. They come in a variety of sizes and bring a pop of color to any room. These hand-woven items are becoming the trendy accessory for Taiwanese homes.</p><p>The Taipei branch may be the newest store in the Sampaga chain, but it is already the most popular. <span class=\"pos\">[4]</span></p>"],"vi":"ĐÀI BẮC (7/10) — Sampaga, cửa hàng đồ nội thất gia đình có trụ sở ở Philippines, đã mở chi nhánh đầu tiên ở Đài Loan khoảng ba tháng trước. Thương hiệu nổi tiếng với các bộ sưu tập đồ gia dụng giá phải chăng, màu sắc tươi sáng và hoa văn vui mắt. Sampaga là cái tên quen thuộc khắp Philippines.\n\nCửa hàng mới nằm ở khu Tây Môn Đình nổi tiếng của Đài Bắc. Cửa hàng không lớn bằng phần lớn các chi nhánh ở Philippines. Tuy nhiên, quản lý cửa hàng, bà Mei-hua Liu, đã thêm ý tưởng riêng: vài phòng nhỏ được bày như phòng trong nhà, trang trí toàn bộ bằng sản phẩm Sampaga. Bà Liu tin điều này giúp khách hình dung sản phẩm trong nhà mình.\n\nMột sản phẩm bán chạy nhất là dòng thảm. Thảm có nhiều kích cỡ và làm bừng sáng màu sắc cho mọi căn phòng. Những tấm thảm dệt tay này đang trở thành món phụ kiện thời thượng trong các gia đình Đài Loan.\n\nChi nhánh Đài Bắc có thể là cửa hàng mới nhất của chuỗi Sampaga, nhưng đã là cửa hàng được yêu thích nhất. Thật vậy, chi nhánh đã phá kỷ lục doanh số lâu năm của công ty ngay trong tháng đầu tiên.","qs":[{"n":158,"q":"What unique feature does the Taipei store have?","qvi":"Cửa hàng Đài Bắc có điểm gì độc đáo?","opts":["Its experienced employees","Its considerable size","Its display rooms","Its convenient location"],"ans":"C","xp":"'its manager... has added her own idea—several small rooms set up like rooms in a house' → các phòng trưng bày → (C). (B) sai: cửa hàng nhỏ hơn các chi nhánh khác."},{"n":159,"q":"What is mentioned about Sampaga's rugs?","qvi":"Điều gì được nhắc đến về thảm của Sampaga?","opts":["They use sustainable materials.","They vary depending on the branch.","They are made by hand.","They are available in custom sizes."],"ans":"C","xp":"'These hand-woven items' → dệt tay → (C). (D) có nhiều kích cỡ sẵn, không nói làm theo kích cỡ riêng."},{"n":160,"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong? \"In fact, the branch broke long-standing company sales records in its first month.\"","qvi":"Câu sau phù hợp nhất ở vị trí nào? \"Thật vậy, chi nhánh đã phá kỷ lục doanh số lâu năm của công ty ngay trong tháng đầu tiên.\"","opts":["[1]","[2]","[3]","[4]"],"ans":"D","xp":"'In fact' bổ sung bằng chứng cho câu trước: 'it is already the most popular' → vị trí [4] → (D)."}]},{"ns":[161,163],"head":"Questions 161-163 refer to the following press release.","passages":["<p>For Immediate Release<br>Ulyerra, PR Director Sharon Lindquist 315-555-7190</p><h3>Ulyerra Helps Ryker Pharmaceuticals to Cut Energy Usage</h3><p>BRISTOL (22 May)—Ryker Pharmaceuticals has implemented a lighting system by Ulyerra to reduce energy consumption and cut the costs of utilities. Using a combination of timers and light sensors, the system is able to program the lights in all buildings in its complex to perfectly match their purpose. Electric lights can be dimmed when natural light levels are high, and lights can be set to turn off automatically in areas that aren't frequently used.</p><p>Site Manager Glenn Bradley was pleased with the results. \"I was able to install the entire system myself, and it was much easier than I expected,\" he said.</p><p>\"I looked into similar systems,\" reported Ryker's General Manager, Marc Coronado, \"but we weren't sure whether or not we were ready for such an investment. Since Ulyerra offered a full refund if we weren't satisfied, I knew it was the right choice.\"</p><p>Just last month, Ryker Pharmaceuticals moved from the fourth-largest to the third-largest supplier of pharmaceuticals in the UK. Its willingness to embrace innovative technologies will certainly take it even further.</p>"],"vi":"Thông cáo báo chí – Ulyerra, Giám đốc PR Sharon Lindquist 315-555-7190\n\nUlyerra giúp Ryker Pharmaceuticals giảm điện năng tiêu thụ\n\nBRISTOL (22/5) — Ryker Pharmaceuticals đã lắp hệ thống chiếu sáng của Ulyerra để giảm tiêu thụ năng lượng và cắt giảm chi phí điện nước. Kết hợp bộ hẹn giờ và cảm biến ánh sáng, hệ thống có thể lập trình đèn ở mọi tòa nhà trong khu phức hợp cho đúng mục đích sử dụng. Đèn điện có thể giảm độ sáng khi ánh sáng tự nhiên nhiều, và có thể tự tắt ở những khu ít dùng.\n\nQuản lý cơ sở Glenn Bradley hài lòng với kết quả. \"Tôi tự lắp được toàn bộ hệ thống, và dễ hơn nhiều so với tôi nghĩ,\" ông nói.\n\n\"Tôi đã tìm hiểu các hệ thống tương tự,\" Tổng giám đốc Ryker, ông Marc Coronado, cho biết, \"nhưng chúng tôi không chắc đã sẵn sàng cho khoản đầu tư như vậy chưa. Vì Ulyerra cam kết hoàn tiền đầy đủ nếu chúng tôi không hài lòng, tôi biết đây là lựa chọn đúng.\"\n\nMới tháng trước, Ryker Pharmaceuticals đã vươn từ nhà cung cấp dược phẩm lớn thứ tư lên thứ ba ở Anh. Tinh thần sẵn sàng đón nhận công nghệ mới chắc chắn sẽ đưa công ty tiến xa hơn nữa.","qs":[{"n":161,"q":"What is suggested about Mr. Bradley?","qvi":"Có thể suy ra điều gì về ông Bradley?","opts":["He invented a light-sensor system.","He prefers to work in natural light.","He performed installations at several buildings.","He has recorded a drop in energy usage."],"ans":"C","xp":"Hệ thống điều khiển đèn 'in all buildings in its complex'; ông Bradley: 'I was able to install the entire system myself' → ông đã lắp đặt ở nhiều tòa nhà → (C)."},{"n":162,"q":"Why did Mr. Coronado choose Ulyerra over its competitors?","qvi":"Vì sao ông Coronado chọn Ulyerra thay vì đối thủ?","opts":["It sold the only system of its kind.","It has the most affordable product on the market.","It was recommended by a colleague.","It came with a money-back guarantee."],"ans":"D","xp":"'Since Ulyerra offered a full refund if we weren't satisfied, I knew it was the right choice' → cam kết hoàn tiền → (D). (A) sai: ông đã xem 'similar systems'."},{"n":163,"q":"What is indicated about Ryker Pharmaceuticals?","qvi":"Điều gì được cho biết về Ryker Pharmaceuticals?","opts":["It was acquired by Ulyerra.","It plans to open an overseas branch.","It has recently gained market share.","It secured a contract with the government."],"ans":"C","xp":"'Just last month, Ryker Pharmaceuticals moved from the fourth-largest to the third-largest supplier' → vừa tăng thị phần → (C)."}]},{"ns":[164,167],"head":"Questions 164-167 refer to the following information.","passages":["<h3>Feeney Accounting On-Site Refreshments</h3><p>Feeney Accounting provides some refreshments to employees and visitors. These are intended to be shared, but some areas are stocked differently than others in order to help us make the best impression while keeping our costs within a reasonable range.</p><ul><li>A bowl of wrapped candy is positioned in the reception area and is intended for short-term visitors.</li><li>The staff meeting room, Room 222, contains instant coffee, tea bags, and a selection of crackers and cookies. Those with allergies should check the packaging before consumption.</li><li>Room 301 has brewed coffee and fresh pastries. These are to be served during meetings with clients only.</li></ul><p>If you need to restock any of the non-perishable foods, you can find them in Room 335. Napkins and cups are also stored there. If we're out of any of the supplies, please inform Vernita Neilsen. However, if the budget for the month has already been spent, they may not be refilled until the following month. If you notice that an area is disorganized and you do not have time to tidy it up yourself, please contact David Haas.</p>"],"vi":"Đồ ăn uống tại công ty kế toán Feeney\n\nFeeney Accounting cung cấp một số đồ ăn uống cho nhân viên và khách. Đồ dùng chung, nhưng mỗi khu được bày khác nhau để tạo ấn tượng tốt nhất mà vẫn giữ chi phí hợp lý.\n- Một bát kẹo gói sẵn đặt ở khu lễ tân, dành cho khách ghé ngắn.\n- Phòng họp nhân viên (phòng 222) có cà phê hòa tan, trà túi lọc và các loại bánh quy. Ai bị dị ứng nên xem bao bì trước khi ăn.\n- Phòng 301 có cà phê pha và bánh ngọt tươi, chỉ dùng trong các buổi gặp khách hàng.\n\nNếu cần bổ sung đồ ăn khô (để lâu được), có thể lấy ở phòng 335. Khăn giấy và cốc cũng để ở đó. Nếu hết đồ, vui lòng báo Vernita Neilsen. Tuy nhiên, nếu ngân sách tháng đã hết thì có thể phải đợi đến tháng sau mới bổ sung. Nếu thấy khu nào bừa bộn mà bạn không có thời gian dọn, hãy liên hệ David Haas.","qs":[{"n":164,"q":"Why was the information written?","qvi":"Thông tin này được viết nhằm mục đích gì?","opts":["To gather food requests before an order","To welcome new visitors to a building","To describe a team's restructuring","To outline a policy at a company"],"ans":"D","xp":"Văn bản trình bày quy định về đồ ăn uống ở từng khu của công ty, cách bổ sung và liên hệ → nêu chính sách của công ty → (D)."},{"n":165,"q":"Where do Feeney Accounting clients most likely have meetings?","qvi":"Khách hàng của Feeney Accounting nhiều khả năng họp ở đâu?","opts":["In Room 222","In Room 301","In Room 335","In the reception area"],"ans":"B","xp":"'Room 301 has brewed coffee and fresh pastries. These are to be served during meetings with clients only' → (B). (A) phòng 222 là phòng họp nhân viên."},{"n":166,"q":"According to the information, why may some areas have no food?","qvi":"Theo thông tin, vì sao có khu có thể hết đồ ăn?","opts":["Some delicate equipment is in operation.","A monthly budget has been reached.","The person in charge is absent.","A health code should not be violated."],"ans":"B","xp":"'if the budget for the month has already been spent, they may not be refilled until the following month' → (B)."},{"n":167,"q":"Why should staff members contact Mr. Haas?","qvi":"Vì sao nhân viên nên liên hệ ông Haas?","opts":["To check on a budget","To ask for more supplies","To report a messy area","To explain food allergies"],"ans":"C","xp":"'If you notice that an area is disorganized... please contact David Haas' → báo khu vực bừa bộn → (C). (B) báo hết đồ thì gặp Vernita Neilsen."}]},{"ns":[168,171],"head":"Questions 168-171 refer to the following online chat discussion.","passages":["<h3>Liberty Hotel Online Chat Service</h3><div class=\"msg\"><p><b>Wen Shao (2:14 P.M.)</b></p><p>I took advantage of the recent offer you advertised on your Web site. It said that Liberty Rewards members who stay three nights or more at Liberty Hotel or any hotel in its network between February 1 and March 31 can receive a voucher for a free night's stay. When I checked out of Gateway Hotel, the front desk clerk said I'd get the voucher in the mail, but there's no sign of it.</p></div><div class=\"msg\"><p><b>Claudia McLeish (2:15 P.M.)</b></p><p>The voucher is valid at both Liberty Hotel and our partners' hotels, and it does not have an expiration date. I'll add Jasper Rautio to this conversation, as he handles Gateway's administration. Could you give me your rewards membership number? That'll help me check into this matter.</p></div><div class=\"msg\"><p><b>Jasper Rautio (2:17 P.M.)</b></p><p>I've got it here. I found Ms. Shao in our system, and her stay from February 8 to February 15 definitely makes her eligible for the voucher.</p></div><div class=\"msg\"><p><b>Wen Shao (2:18 P.M.)</b></p><p>It's R389-07164.</p></div><div class=\"msg\"><p><b>Jasper Rautio (2:19 P.M.)</b></p><p>The voucher will be sent the day after the promotion finishes. We have your mailing address on file. Could I help you to upgrade your Liberty Rewards account to the Premium level, which gives you more benefits?</p></div><div class=\"msg\"><p><b>Wen Shao (2:20 P.M.)</b></p><p>Thanks, but I'm not interested in that. I'll wait for the voucher.</p></div>"],"vi":"Dịch vụ trò chuyện trực tuyến – Khách sạn Liberty\nWen Shao (2:14): Tôi đã dùng ưu đãi quảng cáo gần đây trên trang web của các bạn. Ưu đãi nói hội viên Liberty Rewards ở từ ba đêm trở lên tại khách sạn Liberty hoặc khách sạn trong hệ thống từ 1/2 đến 31/3 sẽ nhận phiếu ở miễn phí một đêm. Khi tôi trả phòng ở khách sạn Gateway, lễ tân nói phiếu sẽ được gửi qua bưu điện, nhưng tôi vẫn chưa thấy đâu.\nClaudia McLeish (2:15): Phiếu dùng được ở cả khách sạn Liberty và các khách sạn đối tác, và không có hạn sử dụng. Tôi sẽ mời Jasper Rautio vào cuộc trò chuyện vì anh ấy phụ trách quản lý khách sạn Gateway. Chị cho tôi số hội viên được không? Như vậy tôi sẽ dễ kiểm tra.\nJasper Rautio (2:17): Tôi có thông tin ở đây rồi. Tôi đã tìm thấy chị Shao trong hệ thống, và kỳ lưu trú từ 8/2 đến 15/2 chắc chắn đủ điều kiện nhận phiếu.\nWen Shao (2:18): Số của tôi là R389-07164.\nJasper Rautio (2:19): Phiếu sẽ được gửi vào ngày sau khi chương trình khuyến mãi kết thúc. Chúng tôi đã có địa chỉ gửi thư của chị. Tôi có thể giúp chị nâng tài khoản Liberty Rewards lên hạng Premium với nhiều quyền lợi hơn không?\nWen Shao (2:20): Cảm ơn, nhưng tôi không quan tâm. Tôi sẽ đợi phiếu.","qs":[{"n":168,"q":"Why did Ms. Shao use the online chat service?","qvi":"Vì sao chị Shao dùng dịch vụ trò chuyện trực tuyến?","opts":["To report that an item was not received","To renew a loyalty program membership","To inquire about how to use a voucher","To cancel a hotel room reservation"],"ans":"A","xp":"'the front desk clerk said I'd get the voucher in the mail, but there's no sign of it' → báo chưa nhận được phiếu → (A)."},{"n":169,"q":"At 2:17 P.M., what does Mr. Rautio suggest when he writes, \"I've got it here\"?","qvi":"Lúc 2:17, ông Rautio ngụ ý gì khi viết \"Tôi có thông tin ở đây rồi\"?","opts":["He can report the invoice number.","He found a lost personal item.","He already looked up some information.","He was able to check a balance."],"ans":"C","xp":"Bà McLeish hỏi số hội viên; ông Rautio nói đã có rồi và 'I found Ms. Shao in our system' → ông đã tra cứu thông tin → (C)."},{"n":170,"q":"What does Mr. Rautio offer to do?","qvi":"Ông Rautio đề nghị làm gì?","opts":["Upgrade Ms. Shao's room reservation","Change Ms. Shao's membership type","Send an account summary to Ms. Shao","Issue a refund to Ms. Shao"],"ans":"B","xp":"'Could I help you to upgrade your Liberty Rewards account to the Premium level' → đổi hạng hội viên → (B). (A) nâng hạng tài khoản, không phải đặt phòng."},{"n":171,"q":"What is NOT indicated about the Liberty Hotel voucher?","qvi":"Điều gì KHÔNG được nói về phiếu của khách sạn Liberty?","opts":["It will be mailed on April 1.","It can be used at sites other than Liberty Hotel.","It gives the user a free stay of three nights.","It does not have an expiration date."],"ans":"C","xp":"(A) gửi 'the day after the promotion finishes' (kết thúc 31/3) → 1/4; (B) dùng được ở khách sạn đối tác; (D) không có hạn. Phiếu cho 'a free night's stay' (một đêm), không phải ba đêm → (C)."}]},{"ns":[172,175],"head":"Questions 172-175 refer to the following letter.","passages":["<p>Sandra Duarte<br>1881 McCabe Drive<br>Oak Hill, VA 20171</p><p>Manuel Bruckner<br>590 Caynor Avenue<br>Herndon, VA 22090</p><p>Dear Mr. Bruckner,</p><p>I was searching through some old records that have now been uploaded as digital copies to the Fairfax County Web site, and they indicated that you are the current owner of the property at 559 Varner Street in Herndon. <span class=\"pos\">[1]</span> You are probably aware that this building is one of the oldest in Herndon, and it features some architectural elements that are rarely found in the region. <span class=\"pos\">[2]</span></p><p>I'm wondering if you would like to form a partnership regarding this building. I understand that it does not meet the building codes, and, therefore, is not permitted for residential or commercial use at this time. It would be a shame if such an old building were to be abandoned or destroyed. <span class=\"pos\">[3]</span> If there is a way to prevent this, that would be the best-case scenario.</p><p>I propose working together to bring this building back to its former glory. I could provide capital to restore the building as part of some kind of partnership arrangement. <span class=\"pos\">[4]</span> I think you'll find that it would be a worthwhile project.</p><p>If you are interested in my offer, please call me so that we may discuss the matter further. My number is 703-555-7193. I hope that I will hear from you soon.</p><p>Kindest regards,<br>Sandra Duarte</p>"],"vi":"Người gửi: Sandra Duarte, 1881 McCabe Drive, Oak Hill | Người nhận: Manuel Bruckner, 590 Caynor Avenue, Herndon\n\nKính gửi ông Bruckner,\n\nTôi đang tìm trong các hồ sơ cũ vừa được số hóa và đăng lên trang web của hạt Fairfax, và hồ sơ cho thấy ông là chủ sở hữu hiện tại của bất động sản ở số 559 phố Varner, Herndon. Có lẽ ông biết tòa nhà này là một trong những tòa nhà cổ nhất ở Herndon, với những chi tiết kiến trúc hiếm thấy trong vùng.\n\nTôi muốn hỏi ông có muốn hợp tác về tòa nhà này không. Tôi hiểu tòa nhà không đáp ứng quy chuẩn xây dựng nên hiện không được phép dùng để ở hay kinh doanh. Thật đáng tiếc nếu một tòa nhà cổ như vậy bị bỏ hoang hay phá hủy. Nếu có cách ngăn điều đó thì là tốt nhất.\n\nTôi đề xuất cùng hợp tác khôi phục vẻ đẹp xưa của tòa nhà. Tôi có thể góp vốn để trùng tu như một phần của thỏa thuận hợp tác. Ví dụ, ông có thể chia cho tôi một phần quyền sở hữu. Tôi nghĩ ông sẽ thấy đây là dự án đáng làm.\n\nNếu quan tâm, xin gọi cho tôi để bàn thêm. Số của tôi là 703-555-7193. Mong sớm nhận tin ông.\n\nTrân trọng,\nSandra Duarte","qs":[{"n":172,"q":"What is true about Fairfax County?","qvi":"Điều gì đúng về hạt Fairfax?","opts":["It has passed stricter building regulations.","It has converted some records to digital form.","Its main office is in the city of Herndon.","It charges a fee for registering a property."],"ans":"B","xp":"'old records that have now been uploaded as digital copies to the Fairfax County Web site' → đã số hóa hồ sơ → (B)."},{"n":173,"q":"What is suggested about Mr. Bruckner's Varner Street property?","qvi":"Có thể suy ra điều gì về bất động sản trên phố Varner của ông Bruckner?","opts":["It cannot be used in its current condition.","It is registered as a residential address.","It used to be a public library.","It has recently been put up for sale."],"ans":"A","xp":"'it does not meet the building codes, and, therefore, is not permitted for residential or commercial use at this time' → hiện không sử dụng được → (A)."},{"n":174,"q":"Why most likely does Ms. Duarte want to form a partnership?","qvi":"Vì sao bà Duarte nhiều khả năng muốn hợp tác?","opts":["She is interested in learning about architecture.","She is looking for a place to run her store.","She wants to protect a historical building.","She has recently entered the real estate business."],"ans":"C","xp":"'It would be a shame if such an old building were to be abandoned or destroyed... bring this building back to its former glory' → bảo tồn tòa nhà cổ → (C)."},{"n":175,"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong? \"You could, for example, provide me with a share of the ownership.\"","qvi":"Câu sau phù hợp nhất ở vị trí nào? \"Ví dụ, ông có thể chia cho tôi một phần quyền sở hữu.\"","opts":["[1]","[2]","[3]","[4]"],"ans":"D","xp":"'for example' là ví dụ cho 'some kind of partnership arrangement' (bà góp vốn, ông chia quyền sở hữu) → đặt sau câu này, vị trí [4] → (D)."}]},{"ns":[176,180],"head":"Questions 176-180 refer to the following e-mail and agenda.","passages":["<div class=\"hdr\"><p><b>To:</b> Department List &lt;departmentstaff@myraco.net&gt;</p><p><b>From:</b> Ranjan Naidu &lt;r_naidu@myraco.net&gt;</p><p><b>Date:</b> July 18</p><p><b>Subject:</b> Monthly Meeting</p></div><p>Dear Team,</p><p>The next departmental monthly meeting for Myra Co. will take place on Thursday, July 20, at 3 P.M. in the main conference room. I've invited Robert Sabo and his department to join us, as the speakers can benefit both teams. The agenda I sent you has one change. Mr. Sabo will take over Mr. Crawford's time slot, and Mr. Crawford's talk will be moved to next month's agenda.</p><p>For those of you who have volunteered to assist with the customer feedback questionnaire, please write down your question ideas before the meeting. We'll meet after the main meeting to discuss which ones should be included.</p><p>See you at the meeting!</p><p>Ranjan</p>","<h3>Myra Co. Departmental Monthly Meeting Agenda</h3><p>July 20, 3:00 P.M. – 6:30 P.M.</p><table><tr><th>Speaker</th><th>Topic</th><th>Details</th></tr><tr><td>Pamela Toth</td><td>Customer Care</td><td>Tips for interacting with customers; How to suggest items to accompany makeup purchases</td></tr><tr><td>Darrell Crawford</td><td>Social Media Strategy</td><td>Review of social media marketing plan</td></tr><tr><td>Maria Elliot, founder of Environment Connect</td><td>Local Outreach</td><td>Weekend volunteer opportunities for Myra Co. employees at this environmental charity</td></tr><tr><td>Augusta Ramos</td><td>Product Demonstration</td><td>Sample the company's new hand cream; Brief feedback session regarding the item's packaging</td></tr><tr><td>Lori Vogel</td><td>Newsletter Launch</td><td>Information on a monthly newsletter for customers and how to contribute articles</td></tr></table>"],"vi":"Người nhận: Danh sách phòng ban | Người gửi: Ranjan Naidu | Ngày: 18/7 | Chủ đề: Họp tháng\n\nGửi cả nhóm,\nBuổi họp hằng tháng của phòng ban Myra Co. sẽ diễn ra vào thứ Năm 20/7, lúc 3 giờ chiều, tại phòng hội nghị chính. Tôi đã mời Robert Sabo và phòng ban của anh ấy cùng tham dự, vì các bài nói có ích cho cả hai nhóm. Chương trình tôi đã gửi có một thay đổi: anh Sabo sẽ nói vào khung giờ của anh Crawford, còn bài của anh Crawford dời sang chương trình tháng sau.\nNhững ai đã tình nguyện giúp làm bảng câu hỏi lấy ý kiến khách hàng, hãy ghi lại ý tưởng câu hỏi trước buổi họp. Chúng ta sẽ gặp nhau sau buổi họp chính để bàn câu nào nên đưa vào.\nHẹn gặp ở buổi họp! – Ranjan\n\nChương trình họp hằng tháng của phòng ban Myra Co. – 20/7, 3:00–6:30 chiều\nPamela Toth – Chăm sóc khách hàng – Mẹo giao tiếp với khách; cách gợi ý sản phẩm đi kèm khi khách mua đồ trang điểm\nDarrell Crawford – Chiến lược mạng xã hội – Xem lại kế hoạch marketing trên mạng xã hội\nMaria Elliot, nhà sáng lập Environment Connect – Hoạt động cộng đồng – Cơ hội tình nguyện cuối tuần cho nhân viên Myra Co. tại tổ chức từ thiện môi trường này\nAugusta Ramos – Giới thiệu sản phẩm – Dùng thử kem dưỡng tay mới của công ty; góp ý nhanh về bao bì\nLori Vogel – Ra mắt bản tin – Thông tin về bản tin hằng tháng cho khách hàng và cách gửi bài","qs":[{"n":176,"q":"What does Mr. Naidu suggest about the meeting in his e-mail?","qvi":"Trong e-mail, ông Naidu gợi ý điều gì về buổi họp?","opts":["Participants will share a meal together after the meeting.","More people will be in attendance than initially expected.","The site of the meeting will be in a different place.","Many of the speakers had to cancel their talks."],"ans":"B","xp":"'I've invited Robert Sabo and his department to join us' → có thêm cả một phòng ban tham dự → đông hơn dự kiến → (B). (D) chỉ một bài bị dời."},{"n":177,"q":"What topic will meeting participants hear about in August?","qvi":"Tháng 8, người dự họp sẽ nghe về chủ đề nào?","opts":["Newsletter Launch","Customer Care","Social Media Strategy","Product Demonstration"],"ans":"C","xp":"'Mr. Crawford's talk will be moved to next month's agenda'; chương trình: Darrell Crawford – Social Media Strategy → (C)."},{"n":178,"q":"What are some employees asked to do prior to the meeting?","qvi":"Một số nhân viên được yêu cầu làm gì trước buổi họp?","opts":["Research the market trends","Order some product samples","Review the sales figures","Prepare some survey questions"],"ans":"D","xp":"'For those of you who have volunteered to assist with the customer feedback questionnaire, please write down your question ideas before the meeting' → (D)."},{"n":179,"q":"According to the agenda, what is true about Ms. Elliot?","qvi":"Theo chương trình, điều gì đúng về bà Elliot?","opts":["She is the newest team member of Myra Co.","She started a local charity.","She will arrive at the meeting late.","She works in Mr. Naidu's department."],"ans":"B","xp":"'Maria Elliot, founder of Environment Connect... this environmental charity' → bà sáng lập một tổ chức từ thiện → (B)."},{"n":180,"q":"What type of goods does Myra Co. most likely sell?","qvi":"Myra Co. nhiều khả năng bán loại hàng gì?","opts":["Footwear","Cosmetics","Office supplies","Power tools"],"ans":"B","xp":"Chương trình: 'makeup purchases', 'the company's new hand cream' → mỹ phẩm → (B)."}]},{"ns":[181,185],"head":"Questions 181-185 refer to the following e-mail and policy information.","passages":["<div class=\"hdr\"><p><b>To:</b> Margaret Wenski &lt;m_wenski@edr1.com&gt;</p><p><b>From:</b> Tae-min Lim &lt;limtaemin@anaheimco.com&gt;</p><p><b>Date:</b> March 2</p><p><b>Subject:</b> From Anaheim Co.</p><p><b>Attachment:</b> anaheimstaff.docx</p></div><p>Dear Ms. Wenski,</p><p>Welcome to Anaheim Co. Your start date will be Monday, March 6. I understand that my colleague, Janet Baxter, figured that it would be best for you to receive the training materials in advance. However, the policy information file that she sent you is from last year. Please delete that file and refer to the attached one instead.</p><p>Monday and Tuesday will be made up of training activities, and then you'll have your first visit to a client's office on Friday. Vincent Trevisan will accompany you, so you will mainly take on an observer role.</p><p>Please note that on your first day, you will be issued your own company laptop with special software loaded onto it. If you have any questions before your first day, please feel free to e-mail me.</p><p>Warmest regards,<br>Tae-min Lim</p>","<h3>Anaheim Co. Policy Information</h3><p><b>Parking</b><br>The northern parking lot is reserved for employees only. The pass needed for this lot can be picked up in the HR office. The southern lot is for visitors, who can purchase an hourly pass at the gate. The cost can be refunded if they show a validated ticket on the way out. The east and west parking lots are a combination of visitor and employee parking. They both require a valid pass. No overnight parking is permitted.</p><p><b>Electronic Equipment</b><br>Employees are responsible for taking care of the electronic equipment assigned to them. Each employee receives a desktop computer, except receptionists in the administration department, who share one computer at the desk. Graphic designers have an additional assigned laptop, one per person. This should be used when working from home due to the software installed on it. Sales team members may check out a laptop from IT if needed for off-site sales presentations. The standard maximum is three days, but this can be extended with a manager's approval.</p>"],"vi":"Người nhận: Margaret Wenski | Người gửi: Tae-min Lim | Ngày: 2/3 | Chủ đề: Từ Anaheim Co. | Đính kèm: anaheimstaff.docx\nKính gửi chị Wenski,\nChào mừng chị đến Anaheim Co. Ngày bắt đầu làm việc của chị là thứ Hai, 6/3. Tôi biết đồng nghiệp của tôi, chị Janet Baxter, nghĩ tốt nhất là chị nên nhận tài liệu đào tạo trước. Tuy nhiên, tệp thông tin chính sách chị ấy gửi là của năm ngoái. Vui lòng xóa tệp đó và xem tệp đính kèm này.\nThứ Hai và thứ Ba là các hoạt động đào tạo, sau đó thứ Sáu chị sẽ lần đầu đến văn phòng khách hàng. Anh Vincent Trevisan sẽ đi cùng, nên chị chủ yếu quan sát.\nLưu ý: ngày đầu tiên chị sẽ được cấp laptop công ty riêng có cài phần mềm chuyên dụng. Nếu có câu hỏi trước ngày đầu, cứ e-mail cho tôi. – Tae-min Lim\n\nThông tin chính sách Anaheim Co.\nBãi đỗ xe: Bãi phía bắc chỉ dành cho nhân viên; thẻ đỗ xe lấy ở phòng nhân sự. Bãi phía nam dành cho khách, khách mua vé theo giờ ở cổng; được hoàn tiền nếu xuất trình vé đã xác nhận khi ra. Bãi phía đông và phía tây dùng chung cho khách và nhân viên, đều cần thẻ hợp lệ. Không được đỗ qua đêm.\nThiết bị điện tử: Nhân viên chịu trách nhiệm giữ gìn thiết bị được cấp. Mỗi nhân viên được một máy tính để bàn, trừ lễ tân phòng hành chính dùng chung một máy ở quầy. Nhà thiết kế đồ họa được cấp thêm mỗi người một laptop, dùng khi làm việc ở nhà vì có cài phần mềm riêng. Nhân viên kinh doanh có thể mượn laptop từ phòng IT khi cần thuyết trình bán hàng bên ngoài, tối đa ba ngày, có thể gia hạn nếu quản lý duyệt.","qs":[{"n":181,"q":"Why did Mr. Lim send the e-mail?","qvi":"Vì sao ông Lim gửi e-mail?","opts":["To explain topics in an orientation session","To provide an updated document","To inform a new employee of a schedule change","To confirm changes to an employment contract"],"ans":"B","xp":"'the policy information file that she sent you is from last year. Please delete that file and refer to the attached one instead' → gửi tài liệu cập nhật → (B)."},{"n":182,"q":"In the e-mail, the word \"figured\" in paragraph 1, line 2, is closest in meaning to","qvi":"Trong e-mail, từ \"figured\" ở đoạn 1, dòng 2 gần nghĩa nhất với","opts":["appeared","followed","computed","thought"],"ans":"D","xp":"'Janet Baxter figured that it would be best...' = nghĩ rằng → (D) thought. (C) computed là nghĩa 'tính toán', không hợp."},{"n":183,"q":"What is suggested about Ms. Wenski?","qvi":"Có thể suy ra điều gì về chị Wenski?","opts":["She will be trained by Ms. Baxter.","She must provide her own computer equipment.","She will meet with a client in March.","She must pass a training test on her first day."],"ans":"C","xp":"Bắt đầu thứ Hai 6/3, 'your first visit to a client's office on Friday' → gặp khách trong tháng 3 → (C). (B) sai: công ty cấp laptop."},{"n":184,"q":"What department will Ms. Wenski most likely work in?","qvi":"Chị Wenski nhiều khả năng làm ở phòng nào?","opts":["Administration","Graphic design","IT","Sales"],"ans":"B","xp":"E-mail: chị được cấp 'your own company laptop with special software'; chính sách: 'Graphic designers have an additional assigned laptop, one per person... due to the software installed on it' → phòng thiết kế đồ họa → (B). (D) nhân viên kinh doanh chỉ mượn laptop khi cần."},{"n":185,"q":"According to the policy information, what is true about all Anaheim Co. parking lots?","qvi":"Theo thông tin chính sách, điều gì đúng với mọi bãi đỗ xe của Anaheim Co.?","opts":["A parking pass is required.","Visitors are allowed to park at no cost.","They each offer the same number of spaces.","Employees can park overnight if needed."],"ans":"A","xp":"Bãi bắc cần thẻ, bãi nam mua vé theo giờ, bãi đông và tây 'both require a valid pass' → bãi nào cũng cần thẻ/vé → (A). (D) sai: 'No overnight parking'."}]},{"ns":[186,190],"head":"Questions 186-190 refer to the following e-mails and memo.","passages":["<div class=\"hdr\"><p><b>To:</b> Eugenia Arcuri &lt;e.arcuri@cunhasoftware.com&gt;</p><p><b>From:</b> Sunder Pandya &lt;s.pandya@cunhasoftware.com&gt;</p><p><b>Date:</b> November 3</p><p><b>Subject:</b> A few suggestions</p></div><p>Dear Ms. Arcuri,</p><p>I continue to receive a lot of complaints about the lack of meeting spaces in our building. I've spoken to other team leaders, who have reported the same problem. Team communication is essential to our operations. Due to this, teams are regularly having to hold meetings after the office closing time, with no additional pay for employees, as it is the only way to get an empty room.</p><p>I believe that the company should reimburse the cost of drinks and food so that teams can meet at a nearby coffee shop. We should also look into renting an additional meeting room off-site to help relieve the pressure. Another option would be to limit the number of team meetings per week so that everyone has a chance to use the room. Thank you for considering my ideas.</p><p>Sincerely,<br>Sunder Pandya</p>","<div class=\"hdr\"><p><b>To:</b> Cunha Software Employees</p><p><b>From:</b> Eugenia Arcuri</p><p><b>Date:</b> November 24</p><p><b>Subject:</b> Meeting rooms</p></div><p>In an effort to improve the meeting room situation at our company, we have rented a private room at Bowman Tower, which is the building next to ours. The room is available all day on Tuesdays and Thursdays. We've also ordered a Zuniga flatscreen TV for our own conference room, which will be delivered on November 27.</p><p>Some of you have been holding small meetings in the break room. Please refrain from doing so, as this is supposed to be a place of rest, and it should be kept as quiet as possible. We will remodel the storage room on the third floor to create a small meeting room that can be used by up to 6 people. I hope the above solutions help resolve the problem.</p>","<div class=\"hdr\"><p><b>To:</b> Eugenia Arcuri &lt;e.arcuri@cunhasoftware.com&gt;</p><p><b>From:</b> Zuniga &lt;orders@zuniga.com&gt;</p><p><b>Date:</b> November 25</p><p><b>Subject:</b> Zuniga Order</p></div><p>Dear Ms. Arcuri,</p><p>Thanks for being a Zuniga customer! We stand by the quality of our products. That's why customers may send items back to the store within 6 weeks of the delivery date. This can be done for any reason, and we will issue you a full refund. Please note that all original packaging materials should be included.</p><p>Are you hanging onto faulty or outdated electronic devices because they cannot go in the regular trash? We've just started a new program to help the environment. We will pick up your old electronics and recycle them properly to prevent harmful chemicals from leaking into our ecosystem. To find out more, visit our Web site.</p><p>Regards,<br>Albert Mills<br>Zuniga Customer Service</p>"],"vi":"Người nhận: Eugenia Arcuri | Người gửi: Sunder Pandya | Ngày: 3/11 | Chủ đề: Vài đề xuất\nKính gửi chị Arcuri, tôi liên tục nhận nhiều phàn nàn về việc thiếu chỗ họp trong tòa nhà. Tôi đã nói chuyện với các trưởng nhóm khác, họ cũng gặp vấn đề tương tự. Giao tiếp trong nhóm rất quan trọng với hoạt động của mình. Vì vậy, các nhóm thường phải họp sau giờ làm, không được trả thêm, vì đó là cách duy nhất để có phòng trống.\nTôi nghĩ công ty nên hoàn tiền đồ uống, đồ ăn để các nhóm có thể họp ở quán cà phê gần đó. Mình cũng nên tính thuê thêm một phòng họp bên ngoài để giảm áp lực. Một cách khác là giới hạn số buổi họp nhóm mỗi tuần để ai cũng có cơ hội dùng phòng. Cảm ơn chị đã xem xét. – Sunder Pandya\n\nGửi: Nhân viên Cunha Software | Từ: Eugenia Arcuri | Ngày: 24/11 | Chủ đề: Phòng họp\nĐể cải thiện tình trạng phòng họp, chúng tôi đã thuê một phòng riêng ở tòa Bowman Tower, tòa nhà bên cạnh. Phòng dùng được cả ngày thứ Ba và thứ Năm. Chúng tôi cũng đã đặt một TV màn hình phẳng Zuniga cho phòng hội nghị của mình, sẽ giao ngày 27/11.\nMột số bạn đã họp nhỏ trong phòng nghỉ. Xin đừng làm vậy, vì đây là nơi nghỉ ngơi và cần giữ yên tĩnh nhất có thể. Chúng tôi sẽ sửa phòng kho tầng 3 thành phòng họp nhỏ cho tối đa 6 người. Mong các giải pháp trên giúp giải quyết vấn đề.\n\nNgười nhận: Eugenia Arcuri | Người gửi: Zuniga | Ngày: 25/11 | Chủ đề: Đơn hàng Zuniga\nKính gửi chị Arcuri, cảm ơn chị đã là khách hàng của Zuniga! Chúng tôi cam kết chất lượng sản phẩm. Vì vậy, khách hàng có thể gửi trả hàng trong vòng 6 tuần kể từ ngày giao, vì bất kỳ lý do gì, và được hoàn tiền đầy đủ. Lưu ý gửi kèm toàn bộ bao bì gốc.\nBạn đang giữ thiết bị điện tử hỏng hay cũ vì không thể bỏ vào thùng rác thường? Chúng tôi vừa bắt đầu chương trình mới vì môi trường: chúng tôi sẽ đến lấy đồ điện tử cũ và tái chế đúng cách để hóa chất độc hại không ngấm ra môi trường. Xem thêm trên trang web của chúng tôi. – Albert Mills, Chăm sóc khách hàng Zuniga","qs":[{"n":186,"q":"According to Mr. Pandya, how has the lack of meeting spaces affected employees?","qvi":"Theo ông Pandya, việc thiếu chỗ họp ảnh hưởng đến nhân viên thế nào?","opts":["They have sent more information by e-mail.","They have changed the size of their teams.","They have had to stay late at the office.","They have had to bring their own equipment."],"ans":"C","xp":"'teams are regularly having to hold meetings after the office closing time' → phải ở lại muộn → (C)."},{"n":187,"q":"Which recommendation made by Mr. Pandya did Ms. Arcuri adopt?","qvi":"Bà Arcuri đã áp dụng đề xuất nào của ông Pandya?","opts":["Renting an off-site location","Holding meetings by teleconference","Reimbursing café spending","Limiting the duration of meetings"],"ans":"A","xp":"Ông đề xuất 'renting an additional meeting room off-site'; bà thông báo 'we have rented a private room at Bowman Tower, which is the building next to ours' → (A)."},{"n":188,"q":"In the memo, what does Ms. Arcuri mention about the break room?","qvi":"Trong thông báo, bà Arcuri nói gì về phòng nghỉ?","opts":["It is located on the third floor.","It will undergo a remodeling project.","Its noise levels should be kept low.","Its space is suitable for small meetings."],"ans":"C","xp":"'this is supposed to be a place of rest, and it should be kept as quiet as possible' → (C). (A)(B) là phòng kho tầng 3."},{"n":189,"q":"What is indicated about the new monitor purchased by Cunha Software?","qvi":"Điều gì được cho biết về màn hình mới Cunha Software mua?","opts":["It will be installed in Bowman Tower.","It was requested by the team leaders.","It was ordered on November 27.","It can be returned anytime in December."],"ans":"D","xp":"TV Zuniga giao ngày 27/11; e-mail Zuniga: 'send items back... within 6 weeks of the delivery date' → được trả đến khoảng 8/1 → trả bất cứ lúc nào trong tháng 12 → (D). (C) 27/11 là ngày giao, không phải ngày đặt."},{"n":190,"q":"What service has Zuniga recently added?","qvi":"Zuniga vừa bổ sung dịch vụ gì?","opts":["Extended warranties","Used electronics recycling","Weekend delivery","Online tracking"],"ans":"B","xp":"'We've just started a new program... We will pick up your old electronics and recycle them' → (B)."}]},{"ns":[191,195],"head":"Questions 191-195 refer to the following article, e-mail, and program.","passages":["<h3>Galway Traditional Music Festival</h3><p>GALWAY (August 7)—Back by popular demand, the Galway Traditional Music Festival is scheduled for October 10-16 this year. The festival was founded by a group of fiddlers who wanted to share their music with a wider audience. Since its founding, the festival has grown in size and has made people interested in traditional Irish music again.</p><p>The festival will mainly take place at Straffan Park. Admission is free to the public, and a total of 50 musicians will put on performances on the outdoor stage. A closing ceremony on the final day of the festival will be held at the Bluebell Center, which is adjacent to the park. This is the only part of the festival that is by invitation only.</p><p>A complete list of performances is available at www.galwaymusic.ie. Visitors are encouraged to take public transportation to the event, as parking at Straffan Park is limited.</p>","<div class=\"hdr\"><p><b>To:</b> Calvin Vaughn</p><p><b>From:</b> Adrienne Kenner</p><p><b>Date:</b> August 10</p><p><b>Subject:</b> RE: Music Festival Awards</p></div><p>Dear Mr. Vaughn,</p><p>I'm delighted to hear that you were able to adjust your schedule to accommodate the festival awards ceremony. We were ready to present your award via teleconferencing, but it's even better that you'll be there to accept it yourself. The doors at the Bluebell Center will open for guests at 6:30 P.M. Bonnie Forbes, the festival's event planner, will introduce you and present the award.</p><p>You will be sent one ticket in the mail, so please provide me with your mailing address at your earliest convenience. It is valid for yourself and a guest of your choice. Please note that tickets are available through the event committee only and are not being sold to the public.</p><p>Warmest regards,<br>Adrienne Kenner<br>Administrator, Galway Traditional Music Festival</p>","<h3>Galway Traditional Music Festival Closing Ceremony</h3><h4>Order of Events</h4><table><tr><td>6:30 P.M.</td><td>Doors Open</td></tr><tr><td>7:00 P.M.</td><td>Welcome Speech by Mayor Amy McDaniel</td></tr><tr><td>7:10 P.M.</td><td>Musical Presentation: Irish fiddle, Darcy Byrne and the Lark Dance Troupe</td></tr><tr><td>8:00 P.M.</td><td>Music Awards presented by Robert Wright</td></tr><tr><td>8:20 P.M.</td><td>Donor Appreciation Award presented by Bonnie Forbes</td></tr><tr><td>8:30 P.M.</td><td>Lifetime Achievement Award presented by Aidan Quinn</td></tr><tr><td>8:40 P.M.</td><td>Musical Presentation: Celtic harp, Dylan Flynn</td></tr><tr><td>9:30 P.M.</td><td>Closing Speech by Amy McDaniel</td></tr></table>"],"vi":"Lễ hội Âm nhạc Truyền thống Galway\nGALWAY (7/8) — Trở lại theo yêu cầu của đông đảo khán giả, Lễ hội Âm nhạc Truyền thống Galway năm nay diễn ra từ 10 đến 16/10. Lễ hội do một nhóm nghệ sĩ vĩ cầm dân gian sáng lập để đưa âm nhạc của họ đến nhiều người hơn. Từ khi ra đời, lễ hội ngày càng lớn và đã khiến mọi người quan tâm trở lại với âm nhạc truyền thống Ireland.\nLễ hội chủ yếu diễn ra ở công viên Straffan. Vào cửa miễn phí, tổng cộng 50 nhạc sĩ sẽ biểu diễn trên sân khấu ngoài trời. Lễ bế mạc vào ngày cuối sẽ tổ chức tại Trung tâm Bluebell cạnh công viên. Đây là phần duy nhất của lễ hội chỉ dành cho khách được mời.\nDanh sách đầy đủ các tiết mục có tại www.galwaymusic.ie. Khách nên đi phương tiện công cộng vì chỗ đỗ xe ở công viên Straffan có hạn.\n\nNgười nhận: Calvin Vaughn | Người gửi: Adrienne Kenner | Ngày: 10/8 | Chủ đề: RE: Giải thưởng lễ hội âm nhạc\nKính gửi ông Vaughn, tôi rất vui khi biết ông đã sắp xếp được lịch để dự lễ trao giải của lễ hội. Chúng tôi đã sẵn sàng trao giải cho ông qua hội nghị trực tuyến, nhưng tốt hơn nhiều khi ông có mặt nhận giải. Trung tâm Bluebell mở cửa đón khách lúc 6:30 tối. Bà Bonnie Forbes, người tổ chức sự kiện của lễ hội, sẽ giới thiệu và trao giải cho ông.\nÔng sẽ được gửi một vé qua bưu điện, vì vậy xin cho tôi địa chỉ sớm nhất có thể. Vé dùng được cho ông và một khách do ông chọn. Lưu ý vé chỉ do ban tổ chức phát, không bán cho công chúng.\nTrân trọng, Adrienne Kenner – Quản trị viên lễ hội\n\nLễ bế mạc – Trình tự: 6:30 mở cửa | 7:00 thị trưởng Amy McDaniel phát biểu chào mừng | 7:10 biểu diễn: vĩ cầm Ireland, Darcy Byrne và đoàn múa Lark | 8:00 Giải âm nhạc do Robert Wright trao | 8:20 Giải Tri ân Nhà tài trợ do Bonnie Forbes trao | 8:30 Giải Thành tựu trọn đời do Aidan Quinn trao | 8:40 biểu diễn: đàn hạc Celtic, Dylan Flynn | 9:30 Amy McDaniel phát biểu bế mạc.","qs":[{"n":191,"q":"What is indicated about the festival?","qvi":"Điều gì được cho biết về lễ hội?","opts":["It will increase the number of stage shows this year.","It has renewed an interest in an art form.","It has been running for 50 years.","It offers traditional musical instruments for sale."],"ans":"B","xp":"'has made people interested in traditional Irish music again' → làm sống lại sự quan tâm đến một loại hình nghệ thuật → (B). (C) 50 là số nhạc sĩ."},{"n":192,"q":"What is Ms. Kenner pleased about?","qvi":"Bà Kenner vui về điều gì?","opts":["Mr. Vaughn has nominated her for an award.","Mr. Vaughn will make an in-person appearance.","She will be able to get a last-minute ticket.","She was selected to give a speech."],"ans":"B","xp":"'it's even better that you'll be there to accept it yourself' → ông sẽ có mặt trực tiếp → (B)."},{"n":193,"q":"What is implied about the closing event's tickets?","qvi":"Có thể suy ra điều gì về vé lễ bế mạc?","opts":["They should be picked up at the Bluebell Center.","They will generate money to support the festival.","They can be purchased online by customers.","They permit two people to enter with the same ticket."],"ans":"D","xp":"'You will be sent one ticket... It is valid for yourself and a guest of your choice' → một vé cho hai người → (D). (A) vé gửi qua bưu điện, (C) không bán."},{"n":194,"q":"Who most likely is Dylan Flynn?","qvi":"Dylan Flynn nhiều khả năng là ai?","opts":["An event planner","A city official","A performer","A reporter"],"ans":"C","xp":"Chương trình: '8:40 P.M. Musical Presentation: Celtic harp, Dylan Flynn' → người biểu diễn → (C)."},{"n":195,"q":"Why most likely is Mr. Vaughn receiving an award?","qvi":"Vì sao ông Vaughn nhiều khả năng được nhận giải?","opts":["He formed his own musical group.","He has dedicated his life to music.","He made a donation to an event.","He teaches a music class."],"ans":"C","xp":"E-mail: 'Bonnie Forbes... will introduce you and present the award'; chương trình: Bonnie Forbes trao 'Donor Appreciation Award' (giải tri ân nhà tài trợ) → ông đã tài trợ cho sự kiện → (C)."}]},{"ns":[196,200],"head":"Questions 196-200 refer to the following e-mails and letter.","passages":["<div class=\"hdr\"><p><b>To:</b> Sasha Juarez &lt;sashaj@arroya.com.au&gt;</p><p><b>From:</b> Connor Walkom &lt;c_walkom@montagu.com.au&gt;</p><p><b>Date:</b> July 19</p><p><b>Subject:</b> Letter of recommendation</p></div><p>Dear Ms. Juarez,</p><p>Thank you for writing a reference for my application to Carnegie Publishing. I was excited about this opportunity, but ultimately I was not selected for the position. I was required to take an online screening test, which I scored very low on. I thought my experience editing instruction manuals for technical devices when I worked at Montagu would carry over well. However, the test included a lot of literary questions, because the job was for a literary magazine, and my degree and experience are not in that field. I will keep you posted on my job hunt.</p><p>Warmest regards,<br>Connor</p>","<p>Connor Walkom<br>708 Moruya Road<br>BRISBANE QLD 4001</p><p>August 5</p><p>Dear Mr. Walkom,</p><p>On behalf of Bayview Manufacturing, I would like to welcome you to our team. During the interview at our head office, you showed a thorough understanding of our needs. The sample work you provided from Montagu was a perfect fit, as you will have a very similar position here.</p><p>Enclosed you will find the orientation materials for your first day of work, August 12. Please report to work at 9 A.M. You should first go to my office, which is number 211. There you will meet Marvin Carillo, who will be your immediate supervisor. He will conduct the training for you and will introduce you to the rest of the team. At 11:30 A.M., you'll pick up your ID badge from the security department. The lunch plan has not been finalized yet, but it will most likely be in the cafeteria with your team.</p><p>See you on August 12!</p><p>Rafael Prescott</p>","<div class=\"hdr\"><p><b>To:</b> Sasha Juarez &lt;sashaj@arroya.com.au&gt;</p><p><b>From:</b> Connor Walkom &lt;c_walkom@montagu.com.au&gt;</p><p><b>Date:</b> August 7</p><p><b>Subject:</b> Success!</p></div><p>Dear Ms. Juarez,</p><p>I've been offered a job with Bayview Manufacturing. In fact, I was given the employment contract at the close of my interview! This job is a perfect fit for me, and I appreciate your work in writing recommendation letters throughout my job search.</p><p>Warmest regards,<br>Connor</p>"],"vi":"Người nhận: Sasha Juarez | Người gửi: Connor Walkom | Ngày: 19/7 | Chủ đề: Thư giới thiệu\nKính gửi chị Juarez, cảm ơn chị đã viết thư giới thiệu cho đơn ứng tuyển của tôi vào Carnegie Publishing. Tôi rất hào hứng với cơ hội này, nhưng cuối cùng không được chọn. Tôi phải làm bài kiểm tra sàng lọc trực tuyến và bị điểm rất thấp. Tôi nghĩ kinh nghiệm biên tập sách hướng dẫn sử dụng thiết bị kỹ thuật khi làm ở Montagu sẽ có ích. Nhưng bài kiểm tra có nhiều câu hỏi về văn học, vì công việc là cho một tạp chí văn học, mà bằng cấp và kinh nghiệm của tôi không thuộc lĩnh vực đó. Tôi sẽ báo chị tình hình tìm việc. – Connor\n\nGửi Connor Walkom, 708 Moruya Road, Brisbane – ngày 5/8\nKính gửi anh Walkom, thay mặt Bayview Manufacturing, tôi chào mừng anh gia nhập. Trong buổi phỏng vấn ở trụ sở chính, anh đã thể hiện hiểu biết sâu sắc về nhu cầu của chúng tôi. Mẫu công việc anh làm ở Montagu rất phù hợp, vì anh sẽ đảm nhận vị trí rất giống ở đây.\nKèm theo là tài liệu định hướng cho ngày làm việc đầu tiên, 12/8. Vui lòng có mặt lúc 9 giờ sáng. Trước tiên, anh đến văn phòng tôi, phòng 211. Ở đó anh sẽ gặp Marvin Carillo, cấp trên trực tiếp của anh. Anh ấy sẽ đào tạo và giới thiệu anh với cả nhóm. Lúc 11:30, anh đến phòng an ninh nhận thẻ nhân viên. Bữa trưa chưa chốt, nhưng nhiều khả năng sẽ ăn ở căng tin cùng nhóm. Hẹn gặp anh ngày 12/8! – Rafael Prescott\n\nNgười nhận: Sasha Juarez | Người gửi: Connor Walkom | Ngày: 7/8 | Chủ đề: Thành công!\nKính gửi chị Juarez, tôi đã được Bayview Manufacturing nhận vào làm. Thật ra, tôi được đưa hợp đồng lao động ngay cuối buổi phỏng vấn! Công việc rất hợp với tôi, và tôi cảm ơn chị đã viết thư giới thiệu suốt thời gian tôi tìm việc. – Connor","qs":[{"n":196,"q":"Why was Mr. Walkom not offered a job at Carnegie Publishing?","qvi":"Vì sao anh Walkom không được nhận vào Carnegie Publishing?","opts":["He performed poorly on a test.","He could not provide a copy of his degree.","He arrived late for an interview.","He asked for too high a salary."],"ans":"A","xp":"'I was required to take an online screening test, which I scored very low on' → làm bài kiểm tra kém → (A)."},{"n":197,"q":"What is implied about Mr. Walkom?","qvi":"Có thể suy ra điều gì về anh Walkom?","opts":["He recently completed his university education.","He used to work on Mr. Prescott's team.","He left his job at Montagu because he moved to a new city.","He will review technical manuals for Bayview Manufacturing."],"ans":"D","xp":"E-mail 1: ở Montagu anh 'editing instruction manuals for technical devices'; thư: 'The sample work you provided from Montagu was a perfect fit, as you will have a very similar position here' → anh sẽ biên tập sách hướng dẫn kỹ thuật ở Bayview → (D)."},{"n":198,"q":"Who most likely is Mr. Carillo?","qvi":"Ông Carillo nhiều khả năng là ai?","opts":["A financial specialist","A senior editor","A company investor","An HR director"],"ans":"B","xp":"Ông Carillo là 'your immediate supervisor' (cấp trên trực tiếp) và sẽ đào tạo anh Walkom – người làm biên tập → ông nhiều khả năng là biên tập viên cấp cao → (B)."},{"n":199,"q":"According to the letter, where should Mr. Walkom go at 11:30 A.M. on August 12?","qvi":"Theo thư, lúc 11:30 sáng 12/8 anh Walkom nên đến đâu?","opts":["To a security office","To a break room","To a cafeteria","To Mr. Prescott's office"],"ans":"A","xp":"'At 11:30 A.M., you'll pick up your ID badge from the security department' → (A). (D) văn phòng ông Prescott là nơi đến lúc 9 giờ."},{"n":200,"q":"How did Mr. Walkom receive his contract?","qvi":"Anh Walkom nhận hợp đồng bằng cách nào?","opts":["By e-mail","By fax","In person","By mail"],"ans":"C","xp":"'I was given the employment contract at the close of my interview' → nhận trực tiếp → (C)."}]}]}};
